export function auditMarkMutations(): { baselinePasses: number; results: MarkMutationEvidence[] } {
  const root = fileURLToPath(new URL("../../", import.meta.url));
  const temporaryBase = resolve(tmpdir());
  const fixture = mkdtempSync(join(temporaryBase, "marks-mutation-"));
  const suffix = relative(temporaryBase, fixture);
  if (!suffix || suffix.startsWith("..") || isAbsolute(suffix) || !basename(fixture).startsWith("marks-mutation-")) throw new Error("Unsafe mutation fixture path");
  const logDirectory = join(temporaryBase, "marks-mutation-logs");
  mkdirSync(logDirectory, { recursive: true });
  const args = ["--test", "--test-concurrency=1", "--test-reporter=tap", "--test-skip-pattern=mark result table", "test/marks/marks.test.ts", "test/marks/root-initialization.test.ts", "test/marks/reader-rules.test.ts"];
  const run = (): { status: number | null; output: string; failures: string[] } => {
    const child = spawnSync(process.execPath, args, { cwd: fixture, encoding: "utf8", maxBuffer: 16 * 1024 * 1024 });
    if (child.error) throw child.error;
    const output = child.stdout + child.stderr;
    const failures = [...output.matchAll(/^not ok \d+ - (.+)$/gm)].map(match => match[1] ?? "");
    return { status: child.status, output, failures };
  };
  try {
    for (const directory of ["src", "test"]) cpSync(join(root, directory), join(fixture, directory), { recursive: true });
    cpSync(join(root, "package.json"), join(fixture, "package.json"));
    symlinkSync(join(root, "node_modules"), join(fixture, "node_modules"), process.platform === "win32" ? "junction" : "dir");
    const baseline = run();
    writeFileSync(join(logDirectory, "baseline.tap"), baseline.output);
    const baselinePasses = Number(baseline.output.match(/^# pass (\d+)$/m)?.[1]);
    if (baseline.status !== 0 || !baselinePasses) throw new Error(`Baseline failed: ${join(logDirectory, "baseline.tap")}`);
    const results: MarkMutationEvidence[] = [];
    for (const mutation of markMutationDefinitions) {
      const originals = new Map<string, string>();
      try {
        for (const edit of mutation.edits) {
          const path = join(fixture, edit.file);
          const source = readFileSync(path, "utf8");
          if (!originals.has(path)) originals.set(path, source);
          const pieces = source.split(edit.before);
          if (pieces.length - 1 !== (edit.count ?? 1)) throw new Error(`Mutation target changed: ${mutation.id}`);
          writeFileSync(path, pieces.join(edit.after));
        }
        const result = run();
        writeFileSync(join(logDirectory, `${mutation.id}.tap`), result.output);
        const outcome = result.status === 0 ? "SURVIVED" : "DETECTED";
        if (outcome === "DETECTED" && !result.failures.some(name => name.startsWith("A:") || name.startsWith("B:"))) throw new Error(`Mutation caused a load failure: ${mutation.id}`);
        if (outcome !== (mutation.outcome ?? "DETECTED")) throw new Error(`Unexpected ${outcome}: ${mutation.id}; see ${logDirectory}`);
        results.push({ id: mutation.id, outcome, failedTests: result.failures.slice(0, 3), failedTestCount: result.failures.length, edits: mutation.edits });
        console.log(`${mutation.id}: ${outcome} (${result.failures.length} failed tests)`);
      } finally {
        for (const [path, source] of originals) writeFileSync(path, source);
      }
    }
    return { baselinePasses, results };
  } finally {
    rmSync(fixture, { recursive: true, force: true });
  }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const evidence = auditMarkMutations();
  if (process.argv.includes("--write")) writeFileSync(new URL("../../mark-mutations.json", import.meta.url), JSON.stringify(evidence, null, 2) + "\n");
  console.log(`Baseline ${evidence.baselinePasses} passes; ${evidence.results.filter(result => result.outcome === "DETECTED").length} detected, ${evidence.results.filter(result => result.outcome === "SURVIVED").length} survived (claims withdrawn).`);
}

import * as Y from "yjs";
import type { CollabMarks, CollabModel, CollabRow } from "../model.ts";
import { mapValue } from "../schema.ts";
import { readStatusEvent, resolveBeatStatus } from "./status-resolution.ts";
import type { BeatStatusEvent } from "./status-resolution.ts";

interface TagExtent {
  key: string;
  tag: string;
  start: number;
  end: number;
}

export function projectStructuralMarks(model: CollabModel, doc: Y.Doc): void {
  const rejected: { occurrence: string; tag: string; words: string; identities: string[] }[] = [];
  const all = [...model.rows, ...model.recovery.map(entry => entry.row)];
  for (const row of all) {
    const extents = new Map<string, TagExtent>();
    row.characters.forEach((character, index) => {
      for (const [key, value] of Object.entries(character.marks)) {
        if (key.startsWith("t:") && typeof value === "string") {
          const existing = extents.get(key);
          if (existing) existing.end = index + 1;
          else extents.set(key, { key, tag: value, start: index, end: index + 1 });
        }
      }
    });
    const accepted: TagExtent[] = [];
    for (const extent of [...extents.values()].sort((a, b) => a.start - b.start || b.end - a.end || a.key.localeCompare(b.key))) {
      const crossing = accepted.some(other => extent.start < other.end && other.start < extent.end &&
        !(extent.start >= other.start && extent.end <= other.end) && !(other.start >= extent.start && other.end <= extent.end));
      if (crossing || !doc.getMap("tags").has(extent.tag)) {
        rejected.push({ occurrence: extent.key.slice(2), tag: extent.tag, words: row.characters.slice(extent.start, extent.end).map(character => character.value).join(""), identities: row.characters.slice(extent.start, extent.end).map(character => character.notation) });
      } else accepted.push(extent);
    }
    const raw = row.characters.map(character => character.marks);
    row.characters.forEach((character, index) => {
      const marks: Record<string, string | boolean | readonly string[]> = {};
      for (const [key, value] of Object.entries(raw[index] ?? {})) {
        if (!key.startsWith("t:") && !key.startsWith("l:")) marks[key === "cmt" ? `c:${String(value)}` : key] = value;
      }
      const links = Object.entries(raw[index] ?? {}).filter(([key]) => key.startsWith("l:")).sort(([a], [b]) => a.localeCompare(b));
      if (links[0]) marks.href = links[0][1];
      const stack = accepted.filter(extent => extent.start <= index && extent.end > index).sort((a, b) => (b.end - b.start) - (a.end - a.start) || a.key.localeCompare(b.key));
      if (stack[0]) {
        marks.tag = stack[0].tag;
        if (stack.length > 1) marks.innerTags = stack.slice(1).map(extent => extent.tag);
        for (const extent of stack) {
          let link: string | boolean | readonly string[] | undefined;
          for (const original of raw.slice(extent.start, extent.end)) {
            for (const [key, value] of Object.entries(original)) {
              if (key.startsWith("c:")) marks[key] = value;
            }
            const found = Object.entries(original).filter(([key]) => key.startsWith("l:")).sort(([a], [b]) => a.localeCompare(b))[0];
            link ??= found?.[1];
          }
          if (link !== undefined) marks.href = link;
        }
      }
      character.marks = marks;
    });
  }
  if (rejected.length) (model.records ??= {}).tagRecovery = rejected;
}

function plainRecord(value: unknown): Record<string, unknown> {
  if (!(value instanceof Y.Map)) throw new Error("Expected comment/reply record");
  return value.toJSON() as Record<string, unknown>;
}

export function projectComments(model: CollabModel, doc: Y.Doc): void {
  if (!doc.getMap("comments").size && !doc.getMap("replies").size) return;
  const records = (model.records ??= {});
  const replies: (Record<string, unknown> & { id: string })[] = [...doc.getMap("replies")].map(([id, value]) => ({ id, ...plainRecord(value) }));
  replies.sort((a, b) =>
    Number(a.createdAt) - Number(b.createdAt) || a.id.localeCompare(b.id));
  const comments: Record<string, unknown> = {};
  const rows: { row: CollabRow; recovery: boolean }[] = [...model.rows.map(row => ({ row, recovery: false })), ...model.recovery.map(entry => ({ row: entry.row, recovery: true }))];
  for (const [id, value] of [...doc.getMap("comments")].sort(([a], [b]) => a.localeCompare(b))) {
    const original = plainRecord(value);
    const anchor = rows.find(({ row }) => !row.kind && row.characters.some(character => character.marks[`c:${id}`]));
    comments[id] = { ...original, rowId: anchor?.row.id ?? original.rowId, field: anchor ? "audioText" : original.field, recovery: anchor?.recovery ?? true, replies: replies.filter(reply => reply.commentId === id) };
  }
  records.comments = comments;
  records.recoveryReplies = replies.filter(reply => !doc.getMap("comments").has(String(reply.commentId)));
}

export function storedMarkNames(key: string, characters: readonly { text: Y.Text; index: number; notation: string }[]): string[] {
  const result: string[] = [];
  for (const character of characters) {
    let index = 0;
    for (const delta of character.text.toDelta()) {
      const insert: unknown = delta.insert;
      const length = typeof insert === "string" ? insert.length : 1;
      const marks = delta.attributes as CollabMarks | undefined;
      if (index <= character.index && character.index < index + length && marks?.[key]) result.push(character.notation);
      index += length;
    }
  }
  return result;
}

export function projectStatus(model: CollabModel, doc: Y.Doc): void {
  const events: [string, BeatStatusEvent][] = [];
  for (const [id, raw] of doc.getMap("statusEvents")) { const event = readStatusEvent(raw); if (event) events.push([id, event]); }
  if (!events.length) return;
  for (const row of [...model.rows, ...model.recovery.map(entry => entry.row)]) {
    const relevant = events.filter(([, event]) => event.target === row.id);
    if (relevant.length) row.status = resolveBeatStatus(new Map(relevant), doc.getMap("retiredStatus"),
      String(mapValue(doc.getMap("beats").get(row.id)).get("status")));
    const conflict = relevant.filter(([, event]) => relevant.some(([, other]) => event.value !== other.value && JSON.stringify(event.parents) === JSON.stringify(other.parents)));
    if (conflict.length) model.notices = [...new Set(conflict.map(([, event]) => `${event.by}: concurrent status change did not apply`))].sort();
  }
}

import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";
import { statusTimingChanges, validateStatusTimingChanges } from "./status-source-audit.ts";

interface StatusBrowserArchive {
  sourceHead: string;
  files: Record<string, string>;
  bundles: Record<string, { before: string; after: string }>;
  postReviewBundles?: Record<string, { before: string; after: string }>;
  postValidationBundles?: Record<string, { before: string; after: string }>;
}

export async function validateStatusBrowserBundle(entry: string, recorded: string, current: string): Promise<void> {
  const archive = JSON.parse(readFileSync(new URL("status-browser-source.json", import.meta.url), "utf8")) as StatusBrowserArchive;
  assert.equal(archive.sourceHead, "658a5f654a4ecdbd29eb3f28ffd32e911925dab8");
  const declaration = archive.bundles[entry]; assert.ok(declaration);
  assert.equal(recorded, declaration.before);
  const reviewed = archive.postReviewBundles?.[entry];
  if (reviewed) assert.equal(reviewed.before, declaration.after);
  const validated = archive.postValidationBundles?.[entry];
  if (validated) assert.equal(validated.before, reviewed?.after ?? declaration.after);
  assert.equal(current, validated?.after ?? reviewed?.after ?? declaration.after, "Current status bundle differs from its declared post-browser change");
  validateStatusTimingChanges();
  assert.deepEqual(Object.keys(archive.files).sort(), ["src/marks/commands.ts", "src/marks/projection.ts", "src/structure-reader.ts"]);
  const original = new Map<string, string>();
  for (const [path, source] of Object.entries(archive.files)) {
    const change = statusTimingChanges().files.find(file => file.path === path); assert.ok(change);
    assert.equal(createHash("sha256").update(source).digest("hex"), change.before);
    original.set(fileURLToPath(new URL(`../../${path}`, import.meta.url)).replaceAll("\\", "/"), source);
  }
  const rebuilt = await build({ absWorkingDir: fileURLToPath(new URL("../../../../", import.meta.url)),
    entryPoints: [fileURLToPath(new URL(`../../${entry}`, import.meta.url))], bundle: true, write: false, platform: "browser", format: "iife", target: "es2023",
    plugins: [{ name: "archived-status-reader", setup(builder) {
      builder.onLoad({ filter: /\.ts$/ }, args => {
        const contents = original.get(args.path.replaceAll("\\", "/"));
        return contents === undefined ? undefined : { contents, loader: "ts" };
      });
    } }] });
  const text = rebuilt.outputFiles?.[0]?.text; assert.ok(text);
  assert.equal(createHash("sha256").update(text).digest("hex"), recorded, "Historical browser bundle no longer reproduces exactly");
}

import { AbstractType, Doc } from "yjs";
import { createEncoder, toUint8Array, writeAny } from "lib0/encoding";
import { createDecoder, readAny } from "lib0/decoding";

export interface BeatStatusEvent {
  target: string;
  value: "todo" | "ready" | "shot";
  prior?: unknown;
  parents: readonly string[];
  by: string;
}

export function readStatusEvent(raw: unknown): BeatStatusEvent | null {
  if (!raw || typeof raw !== "object") return null;
  try {
    const constructor: unknown = (raw as { constructor?: unknown }).constructor;
    if (constructor === Doc || constructor === Uint8Array) return null;
    if ((raw instanceof AbstractType || raw instanceof Doc) && ![Object, Number, Boolean, Array, String, Date, BigInt].some(type => type === constructor)) return null;
    const encoded = createEncoder(); writeAny(encoded, raw as Parameters<typeof writeAny>[1]);
    const decoded: unknown = readAny(createDecoder(toUint8Array(encoded)));
    if (!decoded || typeof decoded !== "object" || Array.isArray(decoded) || decoded instanceof Uint8Array) return null;
    for (const key of ["target", "value", "parents", "by"]) if (!Object.prototype.hasOwnProperty.call(decoded, key)) return null;
    const source = decoded as Record<string, unknown>, target = source.target, value = source.value, by = source.by, rawParents = source.parents;
    if (typeof target !== "string" || typeof by !== "string" || value !== "todo" && value !== "ready" && value !== "shot" || !Array.isArray(rawParents)) return null;
    const parents: string[] = [];
    for (let index = 0; index < rawParents.length; index++) {
      const parent: unknown = rawParents[index]; if (typeof parent !== "string") return null;
      parents.push(parent);
    }
    return { target, value, parents, by };
  } catch { return null; }
}

export function statusHeads(events: ReadonlyMap<string, BeatStatusEvent>): string[] {
  const parents = new Set([...events.values()].flatMap(event => event.parents));
  return [...events.keys()].filter(id => !parents.has(id));
}

export function resolveBeatStatus(input: ReadonlyMap<string, unknown>, retired: { has: (id: string) => boolean }, stored: string): string {
  const events = new Map<string, BeatStatusEvent>();
  for (const [id, raw] of input) {
    const event = readStatusEvent(raw); if (typeof id === "string" && event) events.set(id, event);
  }
  if (new Set([...events.values()].map(event => event.target)).size > 1) return stored;
  const pending = new Map<string, number>(), children = new Map<string, string[]>(), ordered: string[] = [];
  for (const [id, event] of events) {
    const parents = new Set(event.parents.filter(parent => events.has(parent)));
    pending.set(id, parents.size);
    if (!parents.size) ordered.push(id);
    for (const parent of parents) { const entries = children.get(parent) ?? []; entries.push(id); children.set(parent, entries); }
  }
  for (let index = 0; index < ordered.length; index++) {
    const id = ordered[index]; if (id === undefined) continue;
    for (const child of children.get(id) ?? []) {
      const count = (pending.get(child) ?? 0) - 1; pending.set(child, count); if (!count) ordered.push(child);
    }
  }
  if (ordered.length !== events.size) return stored;
  const ancestry = new Map<string, Set<string>>();
  const ancestors = (id: string): Set<string> => {
    const cached = ancestry.get(id);
    if (cached) return cached;
    const result = new Set<string>();
    const stack = [...events.get(id)?.parents ?? []];
    while (stack.length) {
      const parent = stack.pop(); if (parent === undefined || result.has(parent) || !events.has(parent)) continue;
      result.add(parent);
      for (const ancestor of events.get(parent)?.parents ?? []) stack.push(ancestor);
    }
    ancestry.set(id, result);
    return result;
  };
  const resolved = new Map<string, string>();
  const resolve = (initial: readonly string[]): string => {
    let heads = initial;
    while (heads.length) {
      const values = heads.map(id => resolved.get(id) ?? stored);
      if (new Set(values).size === 1) return values[0] ?? stored;
      let common: Set<string> | undefined;
      for (const id of heads) {
        const branch = ancestors(id);
        common = common === undefined ? new Set(branch) : new Set([...common].filter(ancestor => branch.has(ancestor)));
      }
      const shared = new Map([...events].filter(([id]) => common?.has(id)));
      heads = statusHeads(shared);
    }
    return stored;
  };
  for (const id of ordered) {
    const event = events.get(id); if (!event) continue;
    resolved.set(id, retired.has(id) ? resolve(event.parents.filter(parent => events.has(parent))) : event.value);
  }
  return resolve(statusHeads(events));
}

import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";

interface StatusTimingChanges {
  trackingIssue: string;
  retainedRows: string;
  dependencies: { before: string; after: string };
  counts: { before: string; after: string };
  files: { path: string; before: string | null; after: string; change: string }[];
  reviewChanges?: { path: string; before: string; after: string }[];
  reviewDependencies?: { before: string; after: string };
  reviewCounts?: { before: string; after: string };
  validationChanges?: { path: string; before: string; after: string }[];
  validationDependencies?: { before: string; after: string };
  validationCounts?: { before: string; after: string };
}

export function statusTimingChanges(): StatusTimingChanges {
  return JSON.parse(readFileSync(new URL("status-timing-changes.json", import.meta.url), "utf8")) as StatusTimingChanges;
}

export function currentStatusHash(path: string): string {
  const changes = statusTimingChanges(), original = changes.files.find(file => file.path === path);
  const validated = changes.validationChanges?.find(file => file.path === path);
  if (!original) { assert.equal(path, "src/perf/operations.ts"); assert.ok(validated); return validated.after; }
  const reviewed = changes.reviewChanges?.find(file => file.path === path);
  if (reviewed) assert.equal(reviewed.before, original.after);
  if (validated) assert.equal(validated.before, reviewed?.after ?? original.after);
  return validated?.after ?? reviewed?.after ?? original.after;
}

export function validateStatusTimingChanges(changes = statusTimingChanges()): void {
  assert.equal(changes.trackingIssue, "https://github.com/RetroGorilla/splitpage/issues/1376");
  assert.equal(new Set(changes.files.map(file => file.path)).size, changes.files.length);
  assert.equal(new Set(changes.reviewChanges?.map(file => file.path)).size, changes.reviewChanges?.length ?? 0);
  assert.equal(new Set(changes.validationChanges?.map(file => file.path)).size, changes.validationChanges?.length ?? 0);
  for (const reviewed of changes.reviewChanges ?? []) {
    const original = changes.files.find(file => file.path === reviewed.path); assert.ok(original);
    assert.equal(reviewed.before, original.after);
  }
  if (changes.reviewDependencies) assert.equal(changes.reviewDependencies.before, changes.dependencies.after);
  if (changes.reviewCounts) assert.equal(changes.reviewCounts.before, changes.counts.after);
  if (changes.validationDependencies) assert.equal(changes.validationDependencies.before, changes.reviewDependencies?.after ?? changes.dependencies.after);
  if (changes.validationCounts) assert.equal(changes.validationCounts.before, changes.reviewCounts?.after ?? changes.counts.after);
  for (const validated of changes.validationChanges ?? []) {
    const original = changes.files.find(file => file.path === validated.path), reviewed = changes.reviewChanges?.find(file => file.path === validated.path);
    if (original) assert.equal(validated.before, reviewed?.after ?? original.after);
    else assert.equal(validated.path, "src/perf/operations.ts");
  }
  assert.deepEqual(changes.files.map(file => file.path).sort(), [
    "src/marks/commands.ts", "src/marks/projection.ts", "src/marks/status-resolution.ts", "src/marks/status-source-audit.ts",
    "src/perf/lifetime/audit.ts", "src/perf/lifetime/projector.ts", "src/perf/lifetime/report.ts", "src/perf/lifetime/status-order.ts",
    "src/perf/report.ts", "src/perf/setup.ts", "src/structure-reader.ts"
  ].sort());
  for (const file of changes.files) {
    const reviewed = changes.reviewChanges?.find(change => change.path === file.path);
    const validated = changes.validationChanges?.find(change => change.path === file.path);
    assert.equal(createHash("sha256").update(readFileSync(new URL(`../../${file.path}`, import.meta.url))).digest("hex"), validated?.after ?? reviewed?.after ?? file.after, `Status source changed: ${file.path}`);
  }
  for (const file of changes.validationChanges?.filter(file => !changes.files.some(original => original.path === file.path)) ?? [])
    assert.equal(createHash("sha256").update(readFileSync(new URL(`../../${file.path}`, import.meta.url))).digest("hex"), file.after, `Status validation source changed: ${file.path}`);
}

import * as Y from "yjs";
import { mapValue, textValue } from "../schema.ts";
import type { SchemaCandidate } from "../schema.ts";
import type { ProjectionBlock } from "../proj/document.ts";
import { readDelta } from "../proj/richtext.ts";
import type { ProjectionDelta } from "../proj/richtext.ts";
import { bag } from "../proj/value.ts";
import { deltaLength, patchDelta, sameDelta } from "./delta.ts";

export interface PerfBlockSpan {
  block: ProjectionBlock;
  text: Y.Text;
  start: number;
  end: number;
}

export class PerfBlockIndex {
  private readonly streams = new Map<Y.Text, ProjectionDelta[]>();
  private readonly parsed = new Map<Y.Text, { head: unknown; spans: PerfBlockSpan[] }>();
  private readonly byText = new Map<Y.Text, PerfBlockSpan[]>();
  spans: PerfBlockSpan[] = [];
  lastLookupSpansScanned = 0;
  readonly doc: Y.Doc;
  readonly candidate: SchemaCandidate;

  constructor(doc: Y.Doc, candidate: SchemaCandidate) {
    this.doc = doc;
    this.candidate = candidate;
    this.refresh([]);
  }

  refresh(events: readonly Y.YEvent<Y.AbstractType<unknown>>[]): Set<string> {
    for (const event of events) if (event instanceof Y.YTextEvent && this.streams.has(event.target)) {
      this.streams.set(event.target, patchDelta(this.streams.get(event.target) ?? [], event.delta));
      this.parsed.delete(event.target);
    }
    const previous = new Map(this.spans.map(span => [`${span.block.kind}:${span.block.id}`, span.block]));
    const spans: PerfBlockSpan[] = [];
    const seen = new Set<string>();
    let current: PerfBlockSpan | undefined;
    const scan = (text: Y.Text, head?: unknown): void => {
      const cached = this.parsed.get(text);
      if (cached && cached.head === head && cached.spans.every(span => !seen.has(`${span.block.kind}:${span.block.id}`))) {
        for (const span of cached.spans) { seen.add(`${span.block.kind}:${span.block.id}`); spans.push(span); }
        current = cached.spans.at(-1);
        return;
      }
      const beginAt = spans.length;
      let index = 0;
      const boundary = (value: unknown, start: number): void => {
        const atom = bag(value);
        const kind = "b" in atom ? "b" : "h";
        const id = String(atom[kind]);
        const key = `${kind}:${id}`;
        if (seen.has(key)) return;
        seen.add(key);
        if (current && current.text === text) current.end = index;
        current = { block: { id, kind, delta: [] }, text, start, end: text.length };
        spans.push(current);
      };
      if (head) boundary(head, 0);
      let delta = this.streams.get(text);
      if (!delta) { delta = readDelta(text); this.streams.set(text, delta); }
      for (const item of delta) {
        if (typeof item.insert === "object" && ("b" in item.insert || "h" in item.insert)) boundary(item.insert, index + 1);
        else {
          if (!current) throw new Error("Content before a boundary");
          current.block.delta.push(item);
        }
        index += deltaLength(item);
      }
      this.parsed.set(text, { head, spans: spans.slice(beginAt) });
    };
    if (this.candidate === "A") scan(this.doc.getText("flow"));
    else for (const id of new Set(this.doc.getArray<string>("order").toArray())) {
      const segment = mapValue(this.doc.getMap("segments").get(id));
      scan(textValue(segment.get("text")), segment.get("head"));
    }
    const changed = new Set<string>();
    for (const span of spans) {
      const key = `${span.block.kind}:${span.block.id}`;
      const old = previous.get(key);
      if (old && sameDelta(old.delta, span.block.delta)) span.block = old;
      else changed.add(span.block.id);
      previous.delete(key);
    }
    for (const block of previous.values()) changed.add(block.id);
    this.spans = spans;
    this.byText.clear();
    for (const span of spans) {
      const group = this.byText.get(span.text) ?? [];
      group.push(span);
      this.byText.set(span.text, group);
    }
    return changed;
  }

  containing(text: Y.AbstractType<unknown>, index: number): PerfBlockSpan | undefined {
    this.lastLookupSpansScanned = 0;
    return text instanceof Y.Text ? this.byText.get(text)?.find(span => {
      this.lastLookupSpansScanned++;
      return span.start <= index && index < span.end;
    }) : undefined;
  }

  locate(id: string): PerfBlockSpan {
    const span = this.spans.find(item => item.block.id === id);
    if (!span) throw new Error(`Missing beat ${id}`);
    return span;
  }
}

import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { build } from "esbuild";
import { createHash } from "node:crypto";
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { isProjectionEntry } from "../proj/entry.ts";
import type { collectStructuralCounts } from "./counts-entry.ts";
import { perfSourceDigest } from "./setup.ts";
import { perfFixtures } from "./fixtures.ts";

export interface PerfStructuralEvidence {
  version: number;
  sourceDigest: string;
  timingStatus: string;
  instrumentation: { source: string; sha256: string }[];
  data: ReturnType<typeof collectStructuralCounts>;
}

export async function structuralCounts(): Promise<PerfStructuralEvidence> {
  const directory = await mkdtemp(join(tmpdir(), "perf-counts-"));
  assert.ok(directory.startsWith(join(tmpdir(), "perf-counts-")), "Count directory escaped its temporary root");
  const instrumentation: PerfStructuralEvidence["instrumentation"] = [];
  try {
    const result = await build({ entryPoints: [fileURLToPath(new URL("counts-entry.ts", import.meta.url))], bundle: true, write: false, platform: "node", format: "esm", target: "es2023",
      alias: { yjs: fileURLToPath(new URL("../../node_modules/yjs/src/index.js", import.meta.url)) },
      plugins: [{ name: "count-pinned-public-position-traversals", setup(builder) {
        builder.onLoad({ filter: /[\\/]yjs[\\/]src[\\/]utils[\\/](RelativePosition|StructStore)\.js$/ }, async args => {
          let source = await readFile(args.path, "utf8");
          instrumentation.push({ source: args.path.split(/[\\/]/).slice(-4).join("/"), sha256: createHash("sha256").update(source).digest("hex") });
          const needles = args.path.endsWith("RelativePosition.js") ? [
            ["while (t !== null) {", "relativeItems"], ["while (n !== null) {", "absoluteItems"]
          ] : [["let mid = structs[right]", "storeProbes"], ["mid = structs[midindex]", "storeProbes"]];
          for (const [needle, counter] of needles) {
            assert.ok(needle && counter);
            assert.equal(source.split(needle).length, 2, `Pinned traversal changed: ${needle}`);
            const increment = `;if(globalThis.perfTraversal)globalThis.perfTraversal.${counter}++;`;
            source = source.replace(needle, needle + increment);
          }
          return { contents: source, loader: "js" };
        });
      } }] });
    const text = result.outputFiles?.[0]?.text;
    if (!text || instrumentation.length !== 2) throw new Error("Missing pinned Yjs traversal instrumentation");
    const path = join(directory, "counts.mjs");
    await writeFile(path, text);
    const fixtures = join(directory, "fixtures.json");
    await writeFile(fixtures, JSON.stringify(perfFixtures()));
    const data = JSON.parse(execFileSync(process.execPath, [path, fixtures], { encoding: "utf8", windowsHide: true, maxBuffer: 8 * 1024 ** 2 })) as ReturnType<typeof collectStructuralCounts>;
    assert.deepEqual(data.controls.map(control => [control.candidate, control.capture.relativeItems, control.lookup.absoluteItems, control.lookup.relativeItems, control.lookup.projectedSpans, control.lookup.storeProbes]), [["A", 8, 3, 4, 2, 6], ["B", 2, 0, 1, 1, 8]]);
    return { version: 1, sourceDigest: perfSourceDigest(), timingStatus: "not measured; deterministic structural counts only", instrumentation: instrumentation.sort((a, b) => a.source.localeCompare(b.source)), data };
  } finally {
    await rm(directory, { recursive: true, force: true });
  }
}

if (isProjectionEntry(import.meta.url) && process.argv.includes("--write")) await writeFile(new URL("structural-results.json", import.meta.url), JSON.stringify(await structuralCounts(), null, 2) + "\n");

import type { ProjectionDelta } from "../proj/richtext.ts";
import type { ProjectionBag } from "../proj/value.ts";

export interface PerfTextChange {
  insert?: string | object | undefined;
  retain?: number | undefined;
  delete?: number | undefined;
  attributes?: Record<string, unknown> | undefined;
}

export function deltaLength(value: ProjectionDelta): number {
  return typeof value.insert === "string" ? value.insert.length : 1;
}

export function patchDelta(source: readonly ProjectionDelta[], changes: readonly PerfTextChange[]): ProjectionDelta[] {
  const result: ProjectionDelta[] = [];
  let index = 0, offset = 0;
  const take = (length: number, keep: boolean, attributes?: Record<string, unknown>): void => {
    while (length > 0) {
      const item = source[index];
      if (!item) throw new Error("Event extends beyond cached text");
      const count = Math.min(length, deltaLength(item) - offset);
      if (keep) {
        const attrs = Object.fromEntries(Object.entries({ ...item.attributes, ...attributes }).filter(([, value]) => value !== null));
        result.push({ insert: typeof item.insert === "string" ? item.insert.slice(offset, offset + count) : item.insert, attributes: attrs });
      }
      length -= count;
      offset += count;
      if (offset === deltaLength(item)) { index++; offset = 0; }
    }
  };
  for (const change of changes) {
    if (change.retain !== undefined) take(change.retain, true, change.attributes);
    if (change.delete !== undefined) take(change.delete, false);
    if (change.insert !== undefined) result.push({ insert: change.insert as string | ProjectionBag, attributes: change.attributes ?? {} });
  }
  while (index < source.length) take(deltaLength(source[index] as ProjectionDelta) - offset, true);
  const compact: ProjectionDelta[] = [];
  for (const item of result) {
    const previous = compact.at(-1);
    if (previous && typeof previous.insert === "string" && typeof item.insert === "string" && sameAttributes(previous.attributes, item.attributes)) previous.insert += item.insert;
    else compact.push(item);
  }
  return compact;
}

function sameAttributes(a: Record<string, unknown> = {}, b: Record<string, unknown> = {}): boolean {
  const keys = Object.keys(a);
  return keys.length === Object.keys(b).length && keys.every(key => a[key] === b[key]);
}

export function sameDelta(a: readonly ProjectionDelta[], b: readonly ProjectionDelta[]): boolean {
  return a.length === b.length && a.every((item, index) => {
    const other = b[index];
    return other && (item.insert === other.insert || (typeof item.insert === "object" && typeof other.insert === "object" && JSON.stringify(item.insert) === JSON.stringify(other.insert))) && sameAttributes(item.attributes, other.attributes);
  });
}

import * as Y from "yjs";
import { mapValue } from "../schema.ts";
import type { SchemaReplica } from "../schema.ts";
import { records } from "../proj/value.ts";
import type { ProjectionBag } from "../proj/value.ts";
import { toDocument } from "../proj/document.ts";
import { serializeProjection } from "../proj/reference.ts";
import { splitPerfBeat, writePerfStatus } from "./operations.ts";

export const historyMix = { typing: 60, deleting: 15, retyping: 15, split: 1, join: 1, retireJoin: 1, remove: 1, restore: 1, status: 2, comment: 3 };

export function applyWritingCycle(replica: SchemaReplica, cycle: number, beat: string, comment: string): number {
  const location = replica.locate(beat);
  let index = location.start + Math.min(10, location.end - location.start);
  const text = "Writing and revising a sentence with ordinary words and spaces.";
  for (let op = 0; op < 60; op++) location.text.insert(index++, text[op % text.length] as string, {});
  for (let op = 0; op < 15; op++) location.text.delete(--index, 1);
  for (let op = 0; op < 15; op++) location.text.insert(index++, "rewritten words "[op] as string, {});
  const split = `history-beat-${cycle}`;
  splitPerfBeat(replica, beat, index - location.start, split);
  replica.join(split, beat, `history-join-${cycle}`);
  replica.doc.getMap("retiredJoins").set(`history-join-${cycle}`, true);
  const after = replica.locate(split);
  const observed = [];
  for (let position = after.start; position < after.end; position++) {
    const identity = Y.createRelativePositionFromTypeIndex(after.text, position, 0).item;
    if (identity) observed.push({ client: identity.client, clock: identity.clock });
  }
  replica.remove(split, `history-removal-${cycle}`, "writer", observed);
  if (cycle % 5 !== 0) replica.restore(split, `history-removal-${cycle}`);
  else {
    replica.remove(split, `history-second-removal-${cycle}`, "writer", observed);
    replica.restore(split, `history-removal-${cycle}`);
  }
  writePerfStatus(replica, beat, `history-status-${cycle}-a`, "ready");
  writePerfStatus(replica, beat, `history-status-${cycle}-b`, "shot");
  const record = mapValue(replica.doc.getMap("comments").get(comment));
  for (let op = 0; op < 3; op++) record.set("text", `Revision ${cycle}, comment ${op}: clarify the wording.`);
  return cycle % 5 === 0 ? 101 : 100;
}

export function retainedCounts(replica: SchemaReplica): ProjectionBag {
  let removedBeats = 0, removalFlags = 0, joinEntries = 0;
  for (const value of replica.doc.getMap("beats").values()) {
    const beat = mapValue(value);
    const removals = mapValue(beat.get("removals"));
    if (removals.size) removedBeats++;
    removalFlags += removals.size;
    joinEntries += mapValue(beat.get("joins")).size;
  }
  const plain = toDocument(replica.doc, replica.candidate);
  const activeRows = records(plain.rows).filter(row => !mapValue(mapValue(replica.doc.getMap("beats").get(String(row.id))).get("removals")).size);
  return { beats: replica.doc.getMap("beats").size, removedBeats, removalFlags, removalRecords: replica.doc.getMap("removalRecords").size,
    joinEntries, retiredJoins: replica.doc.getMap("retiredJoins").size, statusEvents: replica.doc.getMap("statusEvents").size,
    projectedFileBytes: Buffer.byteLength(serializeProjection(plain)), activeFileBytes: Buffer.byteLength(serializeProjection({ ...plain, rows: activeRows })) };
}

import * as Y from "yjs";
import { toDocument } from "../proj/document.ts";
import { records } from "../proj/value.ts";
import type { ProjectionBag } from "../proj/value.ts";
import type { ProjectionDelta } from "../proj/richtext.ts";
import { readDelta } from "../proj/richtext.ts";
import { mapValue, textValue } from "../schema.ts";
import type { SchemaReplica } from "../schema.ts";
import { PerfBlockIndex } from "./blocks.ts";

export class IncrementalProjection {
  readonly replica: SchemaReplica;
  readonly index: PerfBlockIndex;
  document: ProjectionBag;
  lastProjected: string[] = [];
  commits = 0;
  private readonly pending: { root: string; event: Y.YEvent<Y.AbstractType<unknown>>; path: (string | number)[] }[] = [];
  private readonly stops: (() => void)[] = [];
  private readonly anchors = new Map<string, { id: string; field: string }[]>();
  private readonly owners = new Map<string, string>();

  constructor(replica: SchemaReplica) {
    this.replica = replica;
    this.index = new PerfBlockIndex(replica.doc, replica.candidate);
    this.document = toDocument(replica.doc, replica.candidate);
    for (const row of records(this.document.rows)) this.updateAnchors(String(row.id));
    const roots = ["beats", "visuals", "gallery", "comments", "replies", "people", "tags", "shots", "meta", "headings", "statusEvents", "retiredStatus", "removalRecords", "retiredJoins"];
    roots.push(...(replica.candidate === "A" ? ["flow"] : ["segments", "order"]));
    for (const root of roots) {
      const type = replica.doc.share.get(root);
      if (!type) continue;
      const observe = (events: Y.YEvent<Y.AbstractType<unknown>>[]): void => {
        for (const event of events) this.pending.push({ root, event, path: [...event.path] });
      };
      type.observeDeep(observe);
      this.stops.push(() => type.unobserveDeep(observe));
    }
    const after = (): void => { if (this.pending.length) this.commit(); };
    replica.doc.on("afterTransaction", after);
    this.stops.push(() => replica.doc.off("afterTransaction", after));
  }

  private updateAnchors(id: string): void {
    const found: { id: string; field: string }[] = [];
    const collect = (delta: readonly ProjectionDelta[], field: string): void => {
      for (const item of delta) for (const [key, value] of Object.entries(item.attributes ?? {})) {
        if (value && key.startsWith("c:")) found.push({ id: key.slice(2), field });
      }
    };
    const block = this.index.spans.find(span => span.block.id === id)?.block;
    for (const [key, value] of this.replica.doc.getMap("visuals")) {
      const visual = mapValue(value);
      this.owners.set(`visuals:${key}`, String(visual.get("beat")));
      if (visual.get("beat") === id) collect(readDelta(textValue(visual.get("text"))), "visualText");
    }
    if (block) collect(block.delta, "audioText");
    for (const [key, value] of this.replica.doc.getMap("gallery")) this.owners.set(`gallery:${key}`, String(mapValue(value).get("beat")));
    this.anchors.set(id, found);
  }

  private commit(): void {
    const pending = this.pending.splice(0);
    const textEvents = pending.filter(item => ["flow", "segments", "order"].includes(item.root));
    const dirty = textEvents.length ? this.index.refresh(textEvents.map(item => item.event)) : new Set<string>();
    let all = false;
    for (const { root, event, path } of pending) {
      if (root === "tags" || (root === "comments" && event instanceof Y.YMapEvent && (path.length === 0 || event.keysChanged.has("anchorId")))) all = true;
      if (!["beats", "visuals", "gallery"].includes(root)) continue;
      const ids = path.length ? [String(path[0])] : event instanceof Y.YMapEvent ? [...event.keysChanged].map(String) : [];
      for (const id of ids) {
        if (root === "beats") dirty.add(id);
        else {
          const value = this.replica.doc.getMap(root).get(id);
          const old = this.owners.get(`${root}:${id}`);
          if (old) dirty.add(old);
          if (value instanceof Y.Map) dirty.add(String(value.get("beat")));
        }
      }
    }
    if (all) for (const span of this.index.spans) dirty.add(span.block.id);
    const blocks = this.index.spans.map(span => span.block);
    const partial = toDocument(this.replica.doc, this.replica.candidate, { blocks: blocks.filter(block => block.kind === "h" || dirty.has(block.id)) });
    const replacements = new Map(records(partial.rows).map(row => [String(row.id), row]));
    const old = new Map(records(this.document.rows).map(row => [String(row.id), row]));
    const rows = blocks.filter(block => block.kind === "b").map(block => {
      const row = replacements.get(block.id) ?? old.get(block.id);
      if (!row) throw new Error(`No projected row ${block.id}`);
      const previous = old.get(block.id);
      return previous && row !== previous && JSON.stringify(row) === JSON.stringify(previous) ? previous : row;
    });
    for (const id of dirty) this.updateAnchors(id);
    const first = new Map<string, { rowId: string; field: string }>();
    for (const row of rows) for (const anchor of this.anchors.get(String(row.id)) ?? []) {
      if (!first.has(anchor.id)) first.set(anchor.id, { rowId: String(row.id), field: anchor.field });
    }
    for (const comment of records(partial.comments)) {
      const anchor = first.get(String(comment.id));
      if (anchor) Object.assign(comment, anchor);
    }
    const sections: ProjectionBag[] = [];
    let heading: (typeof blocks)[number] | undefined;
    for (const block of blocks) {
      if (block.kind === "h") heading = block;
      else if (heading) {
        const name = heading.delta.map(item => typeof item.insert === "string" ? item.insert : "").join("");
        if (name) sections.push({ id: heading.id, name, firstSceneId: block.id });
        heading = undefined;
      }
    }
    partial.rows = rows;
    if (sections.length || (this.replica.doc.getMap("meta").get("keys") as string[]).includes("sections")) partial.sections = sections;
    else delete partial.sections;
    this.document = partial;
    this.lastProjected = [...replacements.keys()];
    this.commits++;
  }

  destroy(): void { for (const stop of this.stops) stop(); }
}

import assert from "node:assert/strict";
import * as Y from "yjs";
import { length } from "lib0/encoding";
import { mapValue, textValue } from "../../schema.ts";
import type { SchemaReplica } from "../../schema.ts";

export const lifetimeCategories = ["live text items", "deleted text tombstones", "soft-removed beat content", "removal records", "join records and retired ids", "status events", "marks", "order array", "other"] as const;
export type LifetimeByteCategory = typeof lifetimeCategories[number];

export function lifetimeRoot(type: Pick<Y.AbstractType<unknown>, "_item" | "doc">): string {
  let current = type;
  while (current._item) {
    const parent = current._item.parent;
    if (!(parent instanceof Y.AbstractType)) break;
    current = parent;
  }
  for (const [name, value] of type.doc?.share ?? []) if (value === current) return name;
  return "unknown";
}

export function attributeLifetimeBytes(replica: SchemaReplica) {
  const categories = Object.fromEntries(lifetimeCategories.map(key => [key, 0])) as Record<LifetimeByteCategory, number>;
  const removed = new Set([...replica.doc.getMap("beats")].filter(([, value]) => mapValue(mapValue(value).get("removals")).size).map(([id]) => id));
  const soft = new Set<Y.Item>();
  const softParents = new WeakSet<object>();
  const retain = (type: Y.Map<unknown>): void => {
    softParents.add(type);
    for (const value of type.values()) if (value instanceof Y.Map) retain(value); else if (value instanceof Y.Text) softParents.add(value);
  };
  for (const id of removed) retain(mapValue(replica.doc.getMap("beats").get(id)));
  for (const root of ["visuals", "gallery"]) for (const value of replica.doc.getMap(root).values()) {
    const record = mapValue(value); if (removed.has(String(record.get("beat")))) retain(record);
  }
  const scan = (text: Y.Text, initial?: string): void => {
    let beat = initial;
    for (let item = text._start; item; item = item.right) {
      const content = item.content.getContent()[0] as { b?: string } | undefined;
      if (!item.deleted && content && typeof content === "object" && content.b) beat = content.b;
      if (beat && removed.has(beat)) soft.add(item);
    }
  };
  for (const value of replica.doc.getMap("segments").values()) {
    const segment = mapValue(value); scan(textValue(segment.get("text")), (segment.get("head") as { b?: string }).b);
  }
  for (const value of replica.doc.getMap("visuals").values()) {
    const visual = mapValue(value); scan(textValue(visual.get("text")), String(visual.get("beat")));
  }
  const classify = (item: Y.Item): LifetimeByteCategory => {
    if (!(item.parent instanceof Y.AbstractType)) return "other";
    const root = lifetimeRoot(item.parent);
    if (root === "removalRecords") return "removal records";
    if (root === "retiredJoins" || (root === "beats" && item.parent._item?.parentSub === "joins")) return "join records and retired ids";
    if (["statusEvents", "retiredStatus"].includes(root)) return "status events";
    if (root === "order") return "order array";
    if (soft.has(item) || softParents.has(item.parent) || (item.content instanceof Y.ContentType && softParents.has(item.content.type))) return "soft-removed beat content";
    if (item.parent instanceof Y.Text) {
      if (item.deleted) return "deleted text tombstones";
      if (item.content instanceof Y.ContentFormat) return "marks";
      if (item.content instanceof Y.ContentString || item.content instanceof Y.ContentEmbed) return "live text items";
    }
    return "other";
  };
  const write = Y.Item.prototype.write;
  const otherRoots: Record<string, number> = {};
  let itemBytes = 0, items = 0;
  Y.Item.prototype.write = function (encoder, offset): void {
    const start = length(encoder.restEncoder);
    write.call(this, encoder, offset);
    const bytes = length(encoder.restEncoder) - start;
    const category = classify(this);
    categories[category] += bytes; itemBytes += bytes; items++;
    if (category === "other") {
      const root = this.parent instanceof Y.AbstractType ? lifetimeRoot(this.parent) : "unknown";
      otherRoots[root] = (otherRoots[root] ?? 0) + bytes;
    }
  };
  let encoded: Uint8Array;
  try { encoded = Y.encodeStateAsUpdate(replica.doc); } finally { Y.Item.prototype.write = write; }
  const framingDeleteSetAndGcBytes = encoded.length - itemBytes;
  categories.other += framingDeleteSetAndGcBytes;
  assert.equal(Object.values(categories).reduce((sum, value) => sum + value, 0), encoded.length);
  return { encodedBytes: encoded.length, categories, otherRoots, items, framingDeleteSetAndGcBytes };
}

import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { lifetimeSources } from "./source.ts";
import { currentStatusHash, statusTimingChanges, validateStatusTimingChanges } from "../../marks/status-source-audit.ts";

interface LifetimeTimedArchive {
  timedHead: string;
  source: ReturnType<typeof lifetimeSources>;
  defaultDataSha256: string;
  timingsSha256: string;
  files: Record<string, string>;
}

export function readLifetimeTimedArchive(): LifetimeTimedArchive {
  return JSON.parse(readFileSync(new URL("timed-implementation.json", import.meta.url), "utf8")) as LifetimeTimedArchive;
}

export function lifetimeDataHash(value: unknown): string { return createHash("sha256").update(JSON.stringify(value)).digest("hex"); }

function section(text: string, start: string, end: string): string {
  assert.equal(text.split(start).length, 2); assert.equal(text.split(end).length, 2);
  const begin = text.indexOf(start), finish = text.indexOf(end, begin); assert.ok(finish > begin);
  return text.slice(begin, finish);
}

export function validateLifetimeCharacterSource(original: Record<string, string>, current: Record<string, string>): void {
  for (const [file, text] of Object.entries(original)) {
    const now = current[file]; assert.ok(now !== undefined, `Missing timed source ${file}`);
    if (file === "report.ts" || file === "workload.ts") continue;
    if (file === "projector.ts") {
      const declared = statusTimingChanges().files.find(change => change.path === "src/perf/lifetime/projector.ts"); assert.ok(declared);
      assert.equal(createHash("sha256").update(text).digest("hex"), declared.before);
      assert.equal(createHash("sha256").update(now).digest("hex"), currentStatusHash(declared.path), "Changed sampled projector work");
    } else if (file === "record.ts") {
      assert.equal(now.replace('import { validateLifetimeTimingSource } from "./audit.ts";\n', "")
        .replace("validateLifetimeTimingSource(value.source, counts.source);", "assert.deepEqual(value.source, counts.source);"), text, "Changed timing driver or guards");
    } else assert.equal(now, text, `Changed timed dependency ${file}`);
  }
  const oldWorkload = original["workload.ts"], newWorkload = current["workload.ts"]; assert.ok(oldWorkload && newWorkload);
  assert.equal(section(newWorkload, "export function canonicalLifetimeSource()", "\nfunction blockSource"), section(oldWorkload, "export function canonicalLifetimeSource()", "\nfunction blockSource"));
}

export function validateLifetimeTimingSource(recorded: ReturnType<typeof lifetimeSources>, current: ReturnType<typeof lifetimeSources>): void {
  if (recorded.sha256 === current.sha256) { assert.deepEqual(recorded, current); return; }
  const archive = readLifetimeTimedArchive(); assert.deepEqual(recorded, archive.source);
  assert.equal(recorded.sha256, lifetimeDataHash({ files: recorded.files, dependencies: recorded.dependencies, fixture: recorded.fixture }));
  assert.deepEqual(Object.keys(archive.files), Object.keys(recorded.files));
  for (const [file, text] of Object.entries(archive.files)) assert.equal(createHash("sha256").update(text).digest("hex"), recorded.files[file]);
  validateStatusTimingChanges();
  assert.equal(recorded.dependencies, statusTimingChanges().dependencies.before);
  const changes = statusTimingChanges();
  assert.equal(current.dependencies, changes.validationDependencies?.after ?? changes.reviewDependencies?.after ?? changes.dependencies.after); assert.equal(current.fixture, recorded.fixture);
  assert.deepEqual(current, lifetimeSources());
  const files = Object.fromEntries(Object.keys(current.files).map(file => [file, readFileSync(new URL(file, import.meta.url), "utf8")]));
  validateLifetimeCharacterSource(archive.files, files);
  assert.equal(createHash("sha256").update(readFileSync(new URL("timings.json", import.meta.url))).digest("hex"), archive.timingsSha256);
}

import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import * as Y from "yjs";
import { fromDocument, toDocument } from "../../proj/document.ts";
import { readDelta } from "../../proj/richtext.ts";
import type { ProjectionDelta } from "../../proj/richtext.ts";
import { serializeProjection } from "../../proj/reference.ts";
import { records } from "../../proj/value.ts";
import type { ProjectionBag } from "../../proj/value.ts";
import { mapValue, textValue } from "../../schema.ts";
import type { SchemaReplica } from "../../schema.ts";
import { PerfBlockIndex } from "../blocks.ts";
import { applyWritingCycle, retainedCounts } from "../history.ts";
import { scalePerfFixture } from "../fixtures.ts";
import { attributeLifetimeBytes } from "./attribution.ts";
import { countLifetimeRemote } from "./probe.ts";
import { LifetimeHistory, lifetimePlan } from "./workload.ts";
import type { LifetimeOperations } from "./workload.ts";

export function lifetimeCharacters(delta: readonly ProjectionDelta[]): number {
  return delta.reduce((sum, item) => sum + (typeof item.insert === "string" ? item.insert.length
    : "w" in item.insert ? 1 + String(item.insert.w).length : "k" in item.insert ? String(item.insert.label ?? "B-roll:").length : 0), 0);
}

export function lifetimeSize(replica: SchemaReplica) {
  const index = new PerfBlockIndex(replica.doc, "B"), active = new Set<string>();
  let finalCharacters = 0;
  for (const span of index.spans) {
    if (span.block.kind !== "b" || mapValue(mapValue(replica.doc.getMap("beats").get(span.block.id)).get("removals")).size) continue;
    active.add(span.block.id); finalCharacters += lifetimeCharacters(span.block.delta);
  }
  for (const value of replica.doc.getMap("visuals").values()) {
    const visual = mapValue(value); if (active.has(String(visual.get("beat")))) finalCharacters += lifetimeCharacters(readDelta(textValue(visual.get("text"))));
  }
  const plain = toDocument(replica.doc, "B"), projectedFileBytes = Buffer.byteLength(serializeProjection(plain));
  const exportedFileBytes = Buffer.byteLength(serializeProjection({ ...plain, rows: records(plain.rows).filter(row => active.has(String(row.id))) }));
  return { finalCharacters, activeBeats: active.size, projectedFileBytes, exportedFileBytes };
}

export function lifetimeTyped(operations: LifetimeOperations): number { return operations.typing + operations.correctionRetypes + operations.revisionTyping; }

function checkpoint(replica: SchemaReplica, snapshot: string, directory: string) {
  const state = Y.encodeStateAsUpdate(replica.doc);
  writeFileSync(join(directory, snapshot), state);
  const bytes = attributeLifetimeBytes(replica);
  assert.equal(bytes.encodedBytes, state.length);
  const legacy = countLifetimeRemote(state, "legacy"), indexed = countLifetimeRemote(state, "indexed");
  assert.ok(indexed.work.capture.relativeItems > 0, "Missing pinned identity-loop instrumentation");
  assert.equal(indexed.work.structure.records.statusEvents ?? 0, 0);
  return { snapshot, sha256: createHash("sha256").update(state).digest("hex"), ...lifetimeSize(replica), bytes, counts: retainedCounts(replica), legacy, indexed };
}

function realistic(writers: number, directory: string, base: ProjectionBag) {
  const history = new LifetimeHistory(writers, base), checkpoints = [];
  let previousStep: { encodedBytes: number; typedCharacters: number } | null = null;
  const cap: { first: { encodedBytes: number; typedCharacters: number; finalCharacters: number; operations: LifetimeOperations; completedBlocks: number; previousStep: { encodedBytes: number; typedCharacters: number } | null } | null } = { first: null };
  history.onStep = () => {
    const encodedBytes = Y.encodeStateAsUpdate(history.master.doc).length, typedCharacters = lifetimeTyped(history.operations);
    if (!cap.first && encodedBytes >= lifetimePlan.capBytes) cap.first = { encodedBytes, typedCharacters, finalCharacters: lifetimeSize(history.master).finalCharacters,
      operations: { ...history.operations }, completedBlocks: history.blocks, previousStep };
    previousStep = { encodedBytes, typedCharacters };
  };
  try {
    while (history.blocks < lifetimePlan.maxBlocks) {
      history.appendBlock();
      const bytes = Y.encodeStateAsUpdate(history.master.doc).length;
      if ([1, 5, 10, 20].includes(history.blocks) || cap.first) {
        const point = checkpoint(history.master, `realistic-${writers}-block-${history.blocks}.bin`, directory);
        checkpoints.push({ blocks: history.blocks, operations: { ...history.operations }, typedCharacters: lifetimeTyped(history.operations), ...point });
      }
      if (cap.first || bytes >= lifetimePlan.capBytes) break;
    }
    assert.ok(cap.first, "Increase the stated horizon: cap was not reached");
    return { writers, firstCap: cap.first, checkpoints };
  } finally { history.destroy(); }
}

function synthetic(directory: string, base: ProjectionBag) {
  const input = scalePerfFixture(base, 10), replica = fromDocument(input, "B", 10), checkpoints = [];
  const ids = records(input.rows).map(row => String(row.id)), comments = records(input.comments).map(comment => String(comment.id));
  let operations = 0;
  try {
    checkpoints.push({ operations, ...checkpoint(replica, "synthetic-0.bin", directory) });
    for (let cycle = 0; cycle < 500; cycle++) {
      operations += applyWritingCycle(replica, cycle, ids[cycle % ids.length] as string, comments[cycle % comments.length] as string);
      if ([99, 249, 499].includes(cycle)) checkpoints.push({ operations, ...checkpoint(replica, `synthetic-${operations}.bin`, directory) });
    }
    return { cycles: 500, checkpoints };
  } finally { replica.destroy(); }
}

function undoRetention(writers: number, base: ProjectionBag) {
  const history = new LifetimeHistory(writers, base, true);
  try {
    history.appendBlock(); history.synchronize();
    const masterBytes = Y.encodeStateAsUpdate(history.master.doc).length;
    return { writers, masterBytes, localWriters: history.writers.map((writer, index) => {
      const manager = history.undo[index]; assert.ok(manager); assert.ok(manager.undoStack.length <= 200);
      return { writer: index + 1, stackEntries: manager.undoStack.length, encodedBytesWhileUndoRetained: Y.encodeStateAsUpdate(writer.doc).length,
        deletionRanges: manager.undoStack.reduce((sum, item) => sum + [...item.deletions.clients.values()].reduce((count, ranges) => count + ranges.length, 0), 0),
        insertionRanges: manager.undoStack.reduce((sum, item) => sum + [...item.insertions.clients.values()].reduce((count, ranges) => count + ranges.length, 0), 0) };
    }) };
  } finally { history.destroy(); }
}

export function collectLifetimeCounts(directory: string, base: ProjectionBag) {
  return { plan: lifetimePlan, realistic: lifetimePlan.writers.map(writers => realistic(writers, directory, base)), synthetic: synthetic(directory, base), undo: lifetimePlan.writers.map(writers => undoRetention(writers, base)) };
}

import type * as Y from "yjs";
import { mapValue } from "../../schema.ts";
import type { SchemaReplica } from "../../schema.ts";
import { records } from "../../proj/value.ts";
import type { ProjectionBag } from "../../proj/value.ts";
import type { PerfStructureView } from "../operations.ts";
import { readStatusEvent, resolveBeatStatus } from "../../marks/status-resolution.ts";
import type { BeatStatusEvent } from "../../marks/status-resolution.ts";

export class IndexedStructureProjection {
  private readonly events = new Map<string, Map<string, BeatStatusEvent>>();
  private readonly targets = new Map<string, string>();
  private readonly values = new Map<string, { stored: string; value: string }>();
  private readonly status: Y.Map<unknown>;
  private readonly retired: Y.Map<unknown>;
  private readonly changes: (event: Y.YMapEvent<unknown>) => void;
  private readonly retirements: (event: Y.YMapEvent<unknown>) => void;
  statusRecordsRead = 0;
  readonly replica: SchemaReplica;

  constructor(replica: SchemaReplica) {
    this.replica = replica;
    this.status = replica.doc.getMap("statusEvents");
    this.retired = replica.doc.getMap("retiredStatus");
    for (const [id, raw] of this.status) { const event = readStatusEvent(raw); if (event) this.put(id, event); }
    this.changes = event => {
      for (const key of event.keysChanged) {
        const id = String(key);
        const old = this.targets.get(id);
        const value = readStatusEvent(this.status.get(id));
        if (old) { this.events.get(old)?.delete(id); this.values.delete(old); }
        if (value) { this.statusRecordsRead++; this.put(id, value); }
        else this.targets.delete(id);
      }
    };
    this.retirements = event => { for (const key of event.keysChanged) { const target = this.targets.get(String(key)); if (target) this.values.delete(target); } };
    this.status.observe(this.changes);
    this.retired.observe(this.retirements);
  }

  private put(id: string, event: BeatStatusEvent): void {
    const entries = this.events.get(event.target) ?? new Map<string, BeatStatusEvent>();
    entries.set(id, event); this.events.set(event.target, entries); this.targets.set(id, event.target); this.values.delete(event.target);
  }

  private value(id: string, beat: Y.Map<unknown>): string {
    const stored = String(beat.get("status"));
    const cached = this.values.get(id);
    if (cached?.stored === stored) return cached.value;
    const events = this.events.get(id) ?? new Map<string, BeatStatusEvent>();
    this.statusRecordsRead += events.size;
    const value = resolveBeatStatus(events, this.retired, stored);
    if (events.size) this.values.set(id, { stored, value });
    return value;
  }

  view(document: ProjectionBag): PerfStructureView {
    const result: PerfStructureView = { groups: [], recovery: [] }, destinations = new Map<string, PerfStructureView["groups"][number]>();
    for (const row of records(document.rows)) {
      const id = String(row.id), beat = mapValue(this.replica.doc.getMap("beats").get(id));
      if (mapValue(beat.get("removals")).size) { result.recovery.push(id); continue; }
      const joins = mapValue(beat.get("joins"));
      const key = [...joins.keys()].filter(key => !this.replica.doc.getMap("retiredJoins").has(key)).sort()[0];
      const join = key ? joins.get(key) as { into: string; glue: string } : undefined;
      const target = join ? destinations.get(join.into) : undefined;
      const status = this.value(id, beat);
      if (target && join) {
        target.members.push(id); target.narration += join.glue + String(row.audioText ?? "");
        target.visual = [target.visual, String(row.visualText ?? "")].filter(Boolean).join("<br>");
        if (["todo", "ready", "shot"].indexOf(status) > ["todo", "ready", "shot"].indexOf(target.status)) target.status = status;
        destinations.set(id, target);
      } else {
        const group = { id, members: [id], narration: String(row.audioText ?? ""), visual: String(row.visualText ?? ""), status };
        result.groups.push(group); destinations.set(id, group);
      }
    }
    return result;
  }

  destroy(): void { this.status.unobserve(this.changes); this.retired.unobserve(this.retirements); }
}

import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir, freemem } from "node:os";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { setTimeout as delay } from "node:timers/promises";
import { build } from "esbuild";
import { isProjectionEntry } from "../../proj/entry.ts";
import { beforeMeasurement, cpuBusy, perfMachine } from "../conditions.ts";
import { percentile } from "../measure.ts";
import { redactPerfText } from "../privacy.ts";
import type { collectLifetimeCounts } from "./counts.ts";
import { lifetimeProbe } from "./probe.ts";
import { lifetimeSources } from "./source.ts";
import { validateLifetimeTimingSource } from "./audit.ts";
import { canonicalLifetimeSource, lifetimePlan } from "./workload.ts";

export interface LifetimeCountEvidence {
  version: number;
  source: ReturnType<typeof lifetimeSources>;
  node: string;
  instrumentation: { source: string; sha256: string }[];
  data: ReturnType<typeof collectLifetimeCounts>;
}

export const lifetimeTimingMethod = { rounds: 5, warmup: 3, samples: 11, minFreeMemoryBytes: 3 * 1024 ** 3, maxCpuBusyPercent: 35,
  maxConsecutiveRefusals: 3, retryDelayMs: 30000, locks: ["perf", "smoke"],
  otherLoad: "A game was running on the PC during this session; accepted runs retain background CPU before/after and free RAM. Node components omit paint, app derivations, M1 gate/queue, real network, blobs and join/load." };

export function lifetimeSnapshotDirectory(): string { return join(tmpdir(), "collab-b-lifetime-snapshots"); }

export async function recordLifetimeCounts(directory = lifetimeSnapshotDirectory()): Promise<LifetimeCountEvidence> {
  const source = lifetimeSources();
  mkdirSync(directory, { recursive: true });
  const instrumentation: LifetimeCountEvidence["instrumentation"] = [];
  const result = await build({ entryPoints: [fileURLToPath(new URL("count-worker.ts", import.meta.url))], bundle: true, write: false, platform: "node", format: "esm", target: "es2023",
    alias: { yjs: fileURLToPath(new URL("../../../node_modules/yjs/src/index.js", import.meta.url)) },
    plugins: [{ name: "lifetime-public-identity-counters", setup(builder) {
      builder.onLoad({ filter: /[\\/]yjs[\\/]src[\\/]utils[\\/](RelativePosition|StructStore)\.js$/ }, args => {
        let source = readFileSync(args.path, "utf8");
        instrumentation.push({ source: args.path.split(/[\\/]/).slice(-4).join("/"), sha256: createHash("sha256").update(source).digest("hex") });
        const needles = args.path.endsWith("RelativePosition.js") ? [["while (t !== null) {", "relativeItems"], ["while (n !== null) {", "absoluteItems"]]
          : [["let mid = structs[right]", "storeProbes"], ["mid = structs[midindex]", "storeProbes"]];
        for (const [needle, counter] of needles) {
          assert.ok(needle && counter); assert.equal(source.split(needle).length, 2);
          source = source.replace(needle, needle + `;if(globalThis.perfTraversal)globalThis.perfTraversal.${counter}++;`);
        }
        return { contents: source, loader: "js" };
      });
    } }] });
  assert.equal(instrumentation.length, 2);
  const code = result.outputFiles?.[0]?.text; assert.ok(code);
  const worker = join(directory, "counts.mjs"); writeFileSync(worker, code);
  const input = join(directory, "fixture.json"); writeFileSync(input, JSON.stringify(canonicalLifetimeSource()));
  const data = JSON.parse(execFileSync(process.execPath, [worker, directory, input], { encoding: "utf8", windowsHide: true, maxBuffer: 32 * 1024 ** 2 })) as ReturnType<typeof collectLifetimeCounts>;
  assert.deepEqual(lifetimeSources(), source, "Sources changed during count collection");
  return { version: 1, source, node: process.version, instrumentation: instrumentation.sort((a, b) => a.source.localeCompare(b.source)), data };
}

export function validateLifetimeCounts(value: LifetimeCountEvidence): void {
  assert.equal(value.version, 1); assert.deepEqual(value.source, lifetimeSources()); assert.equal(value.node, "v24.22.1");
  assert.deepEqual(value.data.plan, lifetimePlan); assert.equal(value.instrumentation.length, 2);
  assert.deepEqual(value.instrumentation.map(item => item.source), ["yjs/src/utils/RelativePosition.js", "yjs/src/utils/StructStore.js"]);
  for (const item of value.instrumentation) assert.equal(item.sha256, createHash("sha256").update(readFileSync(new URL(`../../../node_modules/${item.source}`, import.meta.url))).digest("hex"));
  assert.deepEqual(value.data.realistic.map(row => row.writers), [2, 6]);
  for (const row of value.data.realistic) {
    assert.ok(row.firstCap.encodedBytes >= lifetimePlan.capBytes);
    assert.ok(row.firstCap.previousStep && row.firstCap.previousStep.encodedBytes < lifetimePlan.capBytes);
    assert.ok(row.checkpoints.length >= 3); assert.equal(row.checkpoints[0]?.blocks, 1);
  }
  assert.deepEqual(value.data.synthetic.checkpoints.map(point => point.operations), [0, 10020, 25050, 50100]);
  const points = [...value.data.realistic.flatMap(row => row.checkpoints), ...value.data.synthetic.checkpoints];
  for (const point of points) {
    assert.ok(Object.values(point.bytes.categories).every(bytes => Number.isInteger(bytes) && bytes >= 0));
    assert.equal(Object.values(point.bytes.categories).reduce((sum, bytes) => sum + bytes, 0), point.bytes.encodedBytes);
    assert.equal(Object.values(point.bytes.otherRoots).reduce((sum, bytes) => sum + bytes, point.bytes.framingDeleteSetAndGcBytes), point.bytes.categories.other);
    assert.match(point.sha256, /^[a-f0-9]{64}$/);
    assert.equal(point.indexed.work.structure.records.statusEvents ?? 0, 0);
    assert.equal(point.indexed.value.projectedBeats, 1);
    assert.equal(point.indexed.work.apply.integratedItems, 1);
    assert.ok(point.indexed.work.capture.relativeItems > 0);
  }
}

export function readLifetimeCounts(): LifetimeCountEvidence { return JSON.parse(readFileSync(new URL("counts.json", import.meta.url), "utf8")) as LifetimeCountEvidence; }

export function lifetimeTimingPoints(evidence: LifetimeCountEvidence) {
  return [...evidence.data.realistic.flatMap(row => row.checkpoints.filter(point => point.blocks === 1 || point.blocks === 10 || point === row.checkpoints.at(-1))
    .map(point => ({ name: `realistic ${row.writers} writers / ${point.blocks} blocks`, snapshot: point.snapshot, sha256: point.sha256 }))),
    ...evidence.data.synthetic.checkpoints.filter(point => point.operations === 50100).map(point => ({ name: "synthetic / 50100 operations", snapshot: point.snapshot, sha256: point.sha256 }))];
}

function timedPoint(point: ReturnType<typeof lifetimeTimingPoints>[number], directory: string, order: readonly ("legacy" | "indexed")[]) {
  if (freemem() < lifetimeTimingMethod.minFreeMemoryBytes) throw new Error("RAM fell below the unchanged 3 GiB guard");
  const state = readFileSync(join(directory, point.snapshot));
  assert.equal(createHash("sha256").update(state).digest("hex"), point.sha256);
  const modes = [];
  for (const mode of order) {
    const probe = lifetimeProbe(state, mode), samples: NonNullable<ReturnType<ReturnType<typeof lifetimeProbe>["run"]>["milliseconds"]>[] = [];
    try {
      for (let trial = -lifetimeTimingMethod.warmup; trial < lifetimeTimingMethod.samples; trial++) {
        const value = probe.run(true); if (trial >= 0) { assert.ok(value.milliseconds); samples.push(value.milliseconds); }
      }
      const p50 = Object.fromEntries(Object.keys(samples[0] ?? {}).map(key => [key, percentile(samples.map(sample => sample[key as keyof typeof sample]), 0.5)]));
      const p95 = Object.fromEntries(Object.keys(samples[0] ?? {}).map(key => [key, percentile(samples.map(sample => sample[key as keyof typeof sample]), 0.95)]));
      modes.push({ mode, target: probe.target, samples, p50, p95 });
    } finally { probe.destroy(); globalThis.gc?.(); }
  }
  return { name: point.name, sha256: point.sha256, modes };
}

export interface LifetimeTimingEvidence {
  version: number; source: ReturnType<typeof lifetimeSources>; sourceHead: string; machine: ReturnType<typeof perfMachine>; method: typeof lifetimeTimingMethod;
  refused: Awaited<ReturnType<typeof beforeMeasurement>>[];
  runs: { round: number; before: Awaited<ReturnType<typeof beforeMeasurement>>; cpuAfter: number; valid: boolean; reason?: string; points: ReturnType<typeof timedPoint>[] }[];
}

export async function recordLifetimeTimings(directory = lifetimeSnapshotDirectory()): Promise<LifetimeTimingEvidence> {
  assert.equal(typeof globalThis.gc, "function", "Run Node with --expose-gc");
  assert.equal(process.version, "v24.22.1");
  const counts = readLifetimeCounts(); validateLifetimeCounts(counts);
  const evidence: LifetimeTimingEvidence = { version: 1, source: lifetimeSources(), sourceHead: execFileSync("git", ["rev-parse", "HEAD"], { encoding: "utf8" }).trim(),
    machine: perfMachine(), method: lifetimeTimingMethod, refused: [], runs: [] };
  const save = (): void => writeFileSync(new URL("timings.json", import.meta.url), JSON.stringify(evidence, null, 2) + "\n");
  for (let round = 0; round < lifetimeTimingMethod.rounds; round++) {
    let accepted = false;
    for (let attempt = 0; attempt < lifetimeTimingMethod.maxConsecutiveRefusals && !accepted; attempt++) {
      globalThis.gc?.(); const before = await beforeMeasurement();
      if (before.freeMemoryBytes < lifetimeTimingMethod.minFreeMemoryBytes || before.cpuBefore > lifetimeTimingMethod.maxCpuBusyPercent || before.forbiddenProcesses.length) {
        evidence.refused.push(before); save(); process.stdout.write(`guard refused ${attempt + 1}/3\n`);
      } else {
        const points: ReturnType<typeof timedPoint>[] = []; let reason: string | undefined;
        try { for (const point of lifetimeTimingPoints(counts)) points.push(timedPoint(point, directory, round % 2 ? ["indexed", "legacy"] : ["legacy", "indexed"])); }
        catch (error) { reason = error instanceof Error ? redactPerfText(error.message) : "Measurement failed"; }
        const cpuAfter = await cpuBusy(); accepted = !reason && cpuAfter <= lifetimeTimingMethod.maxCpuBusyPercent;
        evidence.runs.push({ round, before, cpuAfter, valid: accepted, ...(reason ? { reason } : {}), points }); save();
        process.stdout.write(`round ${round + 1}: ${accepted ? "accepted" : "void"}; CPU ${before.cpuBefore.toFixed(1)}/${cpuAfter.toFixed(1)}%; free ${(before.freeMemoryBytes / 1024 ** 3).toFixed(2)} GiB\n`);
      }
      if (!accepted && attempt < lifetimeTimingMethod.maxConsecutiveRefusals - 1) await delay(lifetimeTimingMethod.retryDelayMs);
    }
    if (!accepted) throw new Error("Stopped after three consecutive guard refusals; no timer retries remain");
  }
  assert.deepEqual(lifetimeSources(), evidence.source, "Sources changed during timing collection");
  return evidence;
}

export function validateLifetimeTimings(value: LifetimeTimingEvidence, counts = readLifetimeCounts()): void {
  assert.equal(value.version, 1);
  validateLifetimeTimingSource(value.source, counts.source); assert.deepEqual(value.method, lifetimeTimingMethod);
  assert.equal(value.machine.node, "v24.22.1"); assert.match(value.sourceHead, /^[a-f0-9]{40}$/);
  const valid = value.runs.filter(run => run.valid); assert.equal(valid.length, 5); assert.deepEqual(valid.map(run => run.round), [0, 1, 2, 3, 4]);
  for (const run of valid) {
    assert.ok(run.before.freeMemoryBytes >= lifetimeTimingMethod.minFreeMemoryBytes); assert.ok(run.before.cpuBefore <= 35 && run.cpuAfter <= 35);
    assert.deepEqual(run.before.forbiddenProcesses, []); assert.equal(run.reason, undefined);
    assert.deepEqual(run.points.map(point => point.name), lifetimeTimingPoints(counts).map(point => point.name));
    for (const [index, point] of run.points.entries()) {
      assert.equal(point.sha256, lifetimeTimingPoints(counts)[index]?.sha256);
      assert.equal(point.modes.length, 2);
      assert.deepEqual(point.modes.map(mode => mode.mode), run.round % 2 ? ["indexed", "legacy"] : ["legacy", "indexed"]);
      for (const mode of point.modes) {
        assert.equal(mode.samples.length, 11);
        const keys = ["applyExcludingIncremental", "incremental", "structure", "component", "capture", "resolve", "withIdentity"];
        assert.deepEqual(Object.keys(mode.p50), keys); assert.deepEqual(Object.keys(mode.p95), keys);
        for (const sample of mode.samples) {
          assert.deepEqual(Object.keys(sample), keys);
          assert.ok(Math.abs(sample.component - sample.applyExcludingIncremental - sample.incremental - sample.structure) < 0.000001);
          assert.ok(Math.abs(sample.withIdentity - sample.component - sample.capture - sample.resolve) < 0.000001);
        }
        for (const [key, median] of Object.entries(mode.p50)) {
          const samples = mode.samples.map(sample => sample[key as keyof typeof sample]);
          assert.ok(samples.every(sample => Number.isFinite(sample) && sample >= 0));
          assert.equal(median, percentile(samples, 0.5)); assert.equal(mode.p95[key], percentile(samples, 0.95));
        }
      }
    }
  }
}

if (isProjectionEntry(import.meta.url)) {
  const supplied = process.argv.indexOf("--snapshots"), directory = supplied >= 0 ? resolve(process.argv[supplied + 1] ?? "") : lifetimeSnapshotDirectory();
  if (process.argv.includes("--counts")) {
    const evidence = await recordLifetimeCounts(directory); validateLifetimeCounts(evidence);
    writeFileSync(new URL("counts.json", import.meta.url), JSON.stringify(evidence, null, 2) + "\n"); process.stdout.write("Deterministic lifetime counts recorded; no clock samples.\n");
  }
  if (process.argv.includes("--time")) await recordLifetimeTimings(directory);
  if (process.argv.includes("--check")) {
    const counts = readLifetimeCounts(); validateLifetimeCounts(counts);
    if (existsSync(new URL("timings.json", import.meta.url))) validateLifetimeTimings(JSON.parse(readFileSync(new URL("timings.json", import.meta.url), "utf8")) as LifetimeTimingEvidence, counts);
    process.stdout.write("Lifetime source, count structure and timing method valid; no timing thresholds checked.\n");
  }
}

