import * as Y from "yjs";
import { videoLinkKey } from "../../../../src/core/document/gallery.ts";
import type { VideoLink } from "../../../../src/core/document/gallery.ts";
import { brollPropKey } from "../../../../src/core/document/broll.ts";
import { IdentityBook } from "../model.ts";
import { SchemaReplica, mapValue, textValue } from "../schema.ts";
import type { SchemaCandidate } from "../schema.ts";
import { deltaToHtml, insertHtml, readDelta } from "./richtext.ts";
import type { ProjectionDelta } from "./richtext.ts";
import { bag, copy, ordered, rank, ranked, readRecord, records, writeRecord } from "./value.ts";
import type { ProjectionBag } from "./value.ts";

const META = ["titleOrigin", "titleVersion", "docId", "wordsPerMinute", "targetSeconds", "paragraphsDecided", "schema"];
const CAPTURE = ["rev", "lastEditedBy", "lastEditedAt", "personColors"];
const BEAT = ["id", "status", "lengthSeconds", "paragraphStart"];
const COMMENT = ["id", "rowId", "field", "anchorId", "author", "createdAt", "updatedAt", "assignee", "kind", "imageValue", "conflictField", "emptyValue", "titleValue"];
const REPLY = ["id", "author", "createdAt"];
const PERSON = ["id", "name"];
const TAG = ["id", "cat", "name", "owner", "notes", "status"];
const SHOT = ["id", "name", "desc", "status", "reshoot", "notes", "audioRef", "location", "owner", "origin"];
const ROW_SPECIAL = ["audioText", "visualText", "updatedAt", "updatedBy", "imageRef", "imageName", "imageAnnotation", "imageLinks", "moreImages", "visualImage"];
const COMMENT_SPECIAL = ["body", "quotedText", "resolved", "resolvedAt", "resolvedBy", "replies"];

export interface ProjectionOptions {
  deriveCue?: boolean;
  blocks?: readonly ProjectionBlock[];
}

function without(source: ProjectionBag, keys: readonly string[]): ProjectionBag {
  return Object.fromEntries(Object.entries(source).filter(([key]) => !keys.includes(key)));
}

function setIf(source: ProjectionBag, sourceKey: string, target: ProjectionBag, targetKey = sourceKey): void {
  if (Object.hasOwn(source, sourceKey)) target[targetKey] = copy(source[sourceKey]);
}

function putRegistry(doc: Y.Doc, root: string, source: unknown, fields: readonly string[]): void {
  records(source).forEach((entry, index) => {
    const value = new Y.Map<unknown>();
    doc.getMap(root).set(String(entry.id), value);
    writeRecord(value, root === "shots" ? without(entry, ["props"]) : entry, fields);
    value.set("keys", Object.keys(entry));
    value.set("rank", rank(index));
    if (root === "shots") {
      const props = new Y.Map<unknown>();
      value.set("props", props);
      records(entry.props).forEach((prop, propIndex) => {
        addProjectionProp(props, prop, propIndex);
      });
    }
  });
}

export function addProjectionProp(props: Y.Map<unknown>, prop: ProjectionBag, index: number): void {
  const record = new Y.Map<unknown>();
  props.set(brollPropKey(String(prop.id ?? ""), String(prop.name ?? "")), record);
  record.set("value", copy(prop));
  record.set("rank", rank(index));
}

export function addProjectionGallerySlot(doc: Y.Doc, row: string, slot: ProjectionBag, index: number, id = `${row}:slot:${index}`): void {
  const value = new Y.Map<unknown>();
  doc.getMap("gallery").set(id, value);
  value.set("beat", row);
  value.set("rank", rank(index));
  value.set("keys", Object.keys(slot));
  const picture: ProjectionBag = {};
  for (const key of ["imageRef", "name", "annotation"]) setIf(slot, key, picture);
  value.set("picture", picture);
  value.set("extra", JSON.stringify(without(slot, ["imageRef", "name", "annotation", "links"])));
  const links = new Y.Map<unknown>();
  value.set("links", links);
  records(slot.links).forEach((link, linkIndex) => {
    const record = new Y.Map<unknown>();
    const key = videoLinkKey(link as VideoLink);
    links.set(key, record);
    writeRecord(record, without(link, ["location"]), ["href", "name", "size", "duration", "poster"]);
    record.set("rank", rank(linkIndex));
  });
}

function addText(replica: SchemaReplica, id: string, kind: "b" | "h", value: string, source: ProjectionBag): void {
  let text: Y.Text;
  if (replica.candidate === "A") {
    text = replica.doc.getText("flow");
    text.insertEmbed(text.length, { [kind]: id }, {});
  } else {
    const segment = new Y.Map<unknown>();
    replica.doc.getMap("segments").set(`seg-${kind}-${id}`, segment);
    segment.set("head", { [kind]: id });
    text = new Y.Text();
    segment.set("text", text);
    replica.doc.getArray<string>("order").push([`seg-${kind}-${id}`]);
  }
  if (kind === "h") text.insert(text.length, value, {});
  else insertHtml(text, value, source.productionTags, source.comments, `${id}:audioText`);
}

export function createProjectionReplica(candidate: SchemaCandidate, client = 10): SchemaReplica {
  const replica = new SchemaReplica(candidate, client, new IdentityBook());
  replica.doc.getMap("headings");
  return replica;
}

export function fromDocument(source: ProjectionBag, candidate: SchemaCandidate, client = 10): SchemaReplica {
  const replica = createProjectionReplica(candidate, client);
  replica.doc.transact(() => {
    const meta = replica.doc.getMap("meta");
    writeRecord(meta, without(source, ["title", "rows", "sections", "comments", "people", "productionTags", "brollShots", ...CAPTURE]), META);
    meta.set("keys", Object.keys(source));
    meta.set("capture", Object.fromEntries(CAPTURE.filter(key => Object.hasOwn(source, key)).map(key => [key, copy(source[key])])));
    const title = new Y.Text();
    meta.set("title", title);
    title.insert(0, String(source.title ?? ""), {});
    putRegistry(replica.doc, "people", source.people, PERSON);
    putRegistry(replica.doc, "tags", source.productionTags, TAG);
    putRegistry(replica.doc, "shots", source.brollShots, SHOT);
    for (const heading of records(source.sections)) {
      const record = new Y.Map<unknown>();
      replica.doc.getMap("headings").set(String(heading.id), record);
      record.set("keys", Object.keys(heading));
    }
    for (const row of records(source.rows)) {
      for (const heading of records(source.sections).filter(value => value.firstSceneId === row.id)) {
        addText(replica, String(heading.id), "h", String(heading.name), source);
      }
      addText(replica, String(row.id), "b", String(row.audioText ?? ""), source);
      const beat = new Y.Map<unknown>();
      replica.doc.getMap("beats").set(String(row.id), beat);
      writeRecord(beat, without(row, ROW_SPECIAL), BEAT);
      beat.set("keys", Object.keys(row));
      const stamp: ProjectionBag = {};
      setIf(row, "updatedBy", stamp, "by");
      setIf(row, "updatedAt", stamp, "at");
      beat.set("stamp", stamp);
      beat.set("joins", new Y.Map<unknown>());
      beat.set("removals", new Y.Map<unknown>());
      const visual = new Y.Map<unknown>();
      replica.doc.getMap("visuals").set(`visual-${String(row.id)}`, visual);
      visual.set("beat", row.id);
      visual.set("rank", rank(0));
      const text = new Y.Text();
      visual.set("text", text);
      insertHtml(text, String(row.visualText ?? ""), source.productionTags, source.comments, `${String(row.id)}:visualText`);
      const first: ProjectionBag = {};
      setIf(row, "imageRef", first);
      setIf(row, "imageName", first, "name");
      setIf(row, "imageAnnotation", first, "annotation");
      setIf(row, "imageLinks", first, "links");
      addProjectionGallerySlot(replica.doc, String(row.id), first, 0);
      records(row.moreImages).forEach((slot, index) => addProjectionGallerySlot(replica.doc, String(row.id), slot, index + 1));
    }
    records(source.comments).forEach((comment, index) => {
      const record = new Y.Map<unknown>();
      replica.doc.getMap("comments").set(String(comment.id), record);
      writeRecord(record, without(comment, COMMENT_SPECIAL), COMMENT);
      record.set("keys", Object.keys(comment));
      record.set("rank", rank(index));
      const resolution: ProjectionBag = {};
      for (const key of ["resolved", "resolvedAt", "resolvedBy"]) setIf(comment, key, resolution);
      record.set("resolution", resolution);
      if (Object.hasOwn(comment, "body")) record.set("text", comment.body);
      if (Object.hasOwn(comment, "quotedText")) record.set("quote", comment.quotedText);
      records(comment.replies).forEach((reply, replyIndex) => {
        const value = new Y.Map<unknown>();
        replica.doc.getMap("replies").set(`${String(comment.id)}:${String(reply.id)}`, value);
        writeRecord(value, without(reply, ["body"]), REPLY);
        value.set("keys", Object.keys(reply));
        value.set("commentId", comment.id);
        value.set("text", reply.body);
        value.set("rank", rank(replyIndex));
      });
    });
  }, "projection-import");
  return replica;
}

export interface ProjectionBlock {
  id: string;
  kind: "b" | "h";
  delta: ProjectionDelta[];
}

export function projectionBlocks(doc: Y.Doc, candidate: SchemaCandidate): ProjectionBlock[] {
  const result: ProjectionBlock[] = [];
  const seen = new Set<string>();
  let current: ProjectionBlock | null = null;
  function boundary(value: ProjectionBag): void {
    const kind = "b" in value ? "b" : "h";
    const id = String(value[kind]);
    const key = `${kind}:${id}`;
    if (seen.has(key)) return;
    seen.add(key);
    current = { id, kind, delta: [] };
    result.push(current);
  }
  function consume(text: Y.Text): void {
    for (const delta of readDelta(text)) {
      if (typeof delta.insert !== "string" && ("b" in delta.insert || "h" in delta.insert)) boundary(delta.insert);
      else {
        if (!current) throw new Error("Content outside a boundary");
        current.delta.push(delta);
      }
    }
  }
  if (candidate === "A") consume(doc.getText("flow"));
  else for (const id of new Set(doc.getArray<string>("order").toArray())) {
    const segment = mapValue(doc.getMap("segments").get(id));
    boundary(bag(segment.get("head")));
    consume(textValue(segment.get("text")));
  }
  return result;
}

function registry(doc: Y.Doc, root: string, fields: readonly string[]): ProjectionBag[] {
  return ranked(doc.getMap(root)).map(([, value]) => {
    const record = readRecord(value, fields);
    if (root === "shots") {
      const props = ranked(mapValue(value.get("props"))).map(([, prop]) => copy(prop.get("value")));
      if (props.length || (value.get("keys") as string[]).includes("props")) record.props = props;
    }
    return ordered(record, value.get("keys"));
  });
}

function galleryFor(doc: Y.Doc, id: string): ProjectionBag[] {
  return ranked(doc.getMap("gallery")).filter(([, value]) => value.get("beat") === id).map(([, value]) => {
    const result = { ...JSON.parse(String(value.get("extra") ?? "{}")) as ProjectionBag, ...copy(bag(value.get("picture"))) };
    const links = ranked(mapValue(value.get("links"))).map(([, link]) => readRecord(link, ["href", "name", "size", "duration", "poster"]));
    if (links.length || (value.get("keys") as string[]).includes("links")) result.links = links;
    return ordered(result, value.get("keys"));
  });
}

export function toDocument(doc: Y.Doc, candidate: SchemaCandidate, options: ProjectionOptions = {}): ProjectionBag {
  const meta = doc.getMap("meta");
  const result = readRecord(meta, META);
  Object.assign(result, copy(bag(meta.get("capture"))));
  result.title = textValue(meta.get("title")).toString();
  result.people = registry(doc, "people", PERSON);
  result.productionTags = registry(doc, "tags", TAG);
  result.brollShots = registry(doc, "shots", SHOT);
  const comments = ranked(doc.getMap("comments")).map(([, value]) => {
    const comment = readRecord(value, COMMENT);
    Object.assign(comment, copy(bag(value.get("resolution"))));
    if (value.has("text")) comment.body = value.get("text");
    if (value.has("quote")) comment.quotedText = value.get("quote");
    comment.replies = ranked(doc.getMap("replies")).filter(([, reply]) => reply.get("commentId") === comment.id).map(([, reply]) => {
      const record = readRecord(reply, REPLY);
      record.body = reply.get("text");
      return ordered(record, reply.get("keys"));
    });
    return ordered(comment, value.get("keys"));
  });
  result.comments = comments;
  const rows: ProjectionBag[] = [];
  const sections: ProjectionBag[] = [];
  const anchors = new Map<string, { rowId: string; field: string }>();
  function collectAnchors(delta: readonly ProjectionDelta[], rowId: string, field: string): void {
    for (const item of delta) for (const [key, value] of Object.entries(item.attributes ?? {})) {
      if (value && key.startsWith("c:") && !anchors.has(key.slice(2))) anchors.set(key.slice(2), { rowId, field });
    }
  }
  let heading: ProjectionBlock | null = null;
  for (const block of options.blocks ?? projectionBlocks(doc, candidate)) {
    if (block.kind === "h") { heading = block; continue; }
    const beat = mapValue(doc.getMap("beats").get(block.id));
    const row = readRecord(beat, BEAT);
    const stamp = bag(beat.get("stamp"));
    setIf(stamp, "by", row, "updatedBy");
    setIf(stamp, "at", row, "updatedAt");
    row.audioText = deltaToHtml(block.delta, result.productionTags, comments, options.deriveCue);
    row.visualText = ranked(doc.getMap("visuals")).filter(([, value]) => value.get("beat") === block.id)
      .map(([, value]) => {
        const delta = readDelta(textValue(value.get("text")));
        collectAnchors(delta, block.id, "visualText");
        return deltaToHtml(delta, result.productionTags, comments, options.deriveCue);
      }).filter(Boolean).join("<br>");
    collectAnchors(block.delta, block.id, "audioText");
    const slots = galleryFor(doc, block.id);
    const first = slots[0] ?? {};
    setIf(first, "imageRef", row);
    setIf(first, "name", row, "imageName");
    setIf(first, "annotation", row, "imageAnnotation");
    setIf(first, "links", row, "imageLinks");
    if (slots.length > 1 || (beat.get("keys") as string[]).includes("moreImages")) row.moreImages = slots.slice(1);
    rows.push(ordered(row, beat.get("keys")));
    if (heading) {
      const name = heading.delta.map(item => typeof item.insert === "string" ? item.insert : "").join("");
      if (name) sections.push(ordered({ id: heading.id, name, firstSceneId: block.id }, mapValue(doc.getMap("headings").get(heading.id)).get("keys")));
      heading = null;
    }
  }
  result.rows = rows;
  for (const comment of comments) {
    const anchor = anchors.get(String(comment.id));
    if (anchor) Object.assign(comment, anchor);
  }
  if (sections.length || (meta.get("keys") as string[]).includes("sections")) result.sections = sections;
  return ordered(result, meta.get("keys"));
}

import type * as Y from "yjs";
import { cleanMarks, defaultTagId, defaultTagOf, settleCues } from "../../../../src/core/text/runs.ts";
import type { Marks, Run } from "../../../../src/core/text/runs.ts";
import { bag, records } from "./value.ts";
import type { ProjectionBag } from "./value.ts";
import { storedRunsToHtml } from "./stored-html.ts";

export interface ProjectionDelta {
  insert: string | ProjectionBag;
  attributes?: Record<string, unknown>;
}

export type ProjectionSurfacePart = { storedHtml: string } | { caretSentinel: "\u200b" };

export function surfaceToDelta(parts: readonly ProjectionSurfacePart[], tags: unknown, comments: unknown): ProjectionDelta[] {
  return htmlToDelta(parts.map(part => "storedHtml" in part ? part.storedHtml : "").join(""), tags, comments);
}

function unescape(value: string): string {
  const entities: Record<string, string> = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: "\u00a0" };
  return value.replace(/&(#x[0-9a-f]+|#\d+|amp|lt|gt|quot|apos|nbsp);/gi, (whole, name: string) => {
    if (name[0] !== "#") return entities[name.toLowerCase()] ?? whole;
    const point = name[1]?.toLowerCase() === "x" ? parseInt(name.slice(2), 16) : Number(name.slice(1));
    return point <= 0x10ffff ? String.fromCodePoint(point) : "\ufffd";
  });
}

function attributes(token: string): Record<string, string> {
  const result = Object.create(null) as Record<string, string>;
  for (const match of token.matchAll(/([\w-]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/g)) {
    result[match[1] as string] = unescape(match[2] ?? match[3] ?? match[4] ?? "");
  }
  return result;
}

function htmlTokens(html: string): string[] {
  const result: string[] = [];
  let start = 0;
  while (start < html.length) {
    if (html[start] !== "<") {
      const next = html.indexOf("<", start);
      const end = next < 0 ? html.length : next;
      result.push(html.slice(start, end));
      start = end;
      continue;
    }
    let quote: string | null = null;
    let end = start + 1;
    for (; end < html.length; end++) {
      const character = html[end];
      if (quote) { if (character === quote) quote = null; }
      else if (character === '"' || character === "'") quote = character;
      else if (character === ">") break;
    }
    if (end === html.length) throw new Error("Unterminated sanitized HTML tag");
    result.push(html.slice(start, end + 1));
    start = end + 1;
  }
  return result;
}

export function htmlToDelta(html: string, tags: unknown, comments: unknown): ProjectionDelta[] {
  const registry = records(tags);
  const anchors = records(comments);
  const result: ProjectionDelta[] = [];
  const stack: { name: string; attrs: Record<string, unknown> }[] = [];
  let serial = 0;
  let atom: { value: ProjectionBag; attrs: Record<string, unknown>; depth: number; label: string } | null = null;
  function current(): Record<string, unknown> {
    return Object.assign({}, ...stack.map(entry => entry.attrs)) as Record<string, unknown>;
  }
  for (const token of htmlTokens(html)) {
    if (token[0] !== "<") {
      if (atom) atom.label += unescape(token);
      else result.push({ insert: unescape(token).replace(/[\n\r]/g, " "), attributes: current() });
      continue;
    }
    const name = /^<\/?([\w-]+)/.exec(token)?.[1]?.toLowerCase();
    if (!name) continue;
    if (token.startsWith("</")) {
      const index = stack.findLastIndex(entry => entry.name === name);
      if (index >= 0) stack.length = index;
      if (atom && stack.length < atom.depth) {
        if ("k" in atom.value) atom.value.label = atom.label;
        result.push({ insert: atom.value, attributes: atom.attrs });
        atom = null;
      }
      continue;
    }
    if (name === "br") {
      if (!atom) result.push({ insert: "\n", attributes: current() });
      continue;
    }
    const source = attributes(token);
    const attrs: Record<string, unknown> = {};
    const format: Record<string, string> = { strong: "b", b: "b", em: "i", i: "i", u: "u", s: "s", strike: "s", mark: "hl" };
    if (format[name]) attrs[format[name] as string] = true;
    const classes = (source.class ?? "").split(/\s+/);
    if (classes.includes("stage-dir")) attrs.dir = true;
    if (classes.includes("audio-cue")) attrs.cue = true;
    if (source.href) attrs[`l:${++serial}`] = source.href;
    if (source["data-cmt"]) {
      const anchor = source["data-cmt"];
      const comment = anchors.find(value => value.anchorId === anchor);
      attrs[`c:${String(comment?.id ?? anchor)}`] = true;
    }
    if (classes.includes("tag-anchor")) {
      const tag = registry.find(value => value.cat === source["data-tag-cat"] && value.name === source["data-tag-name"]);
      attrs[`t:${String(++serial).padStart(10, "0")}`] = tag?.id ?? defaultTagId(source["data-tag-cat"] ?? "", source["data-tag-name"] ?? "");
    }
    stack.push({ name, attrs });
    if (classes.includes("broll-key") || classes.includes("who-anchor")) {
      atom = {
        value: classes.includes("broll-key") ? { k: source["data-broll-id"] } : { w: source["data-who"] },
        attrs: current(), depth: stack.length, label: ""
      };
    }
  }
  return result;
}

export function deltaToRuns(delta: readonly ProjectionDelta[], tags: unknown, comments: unknown, deriveCue = false): Run[] {
  const registry = records(tags);
  const anchors = records(comments);
  const result: Run[] = [];
  for (const item of delta) {
    const attrs = item.attributes ?? {};
    const marks: Marks = cleanMarks(attrs, typeof item.insert !== "string");
    const cmts = Object.keys(attrs).filter(key => key.startsWith("c:") && attrs[key])
      .map(key => String(anchors.find(comment => comment.id === key.slice(2))?.anchorId ?? key.slice(2)));
    if (cmts.length) marks.cmt = cmts.sort();
    const links = Object.keys(attrs).filter(key => key.startsWith("l:") && attrs[key]).sort();
    if (links.length) marks.href = String(attrs[links[0] as string]);
    const tagged = Object.keys(attrs).filter(key => key.startsWith("t:") && attrs[key]).sort()
      .map(key => String(attrs[key])).filter(id => registry.some(tag => tag.id === id) || defaultTagOf(id));
    if (typeof item.insert === "string") {
      if (tagged[0]) marks.tag = tagged[0];
      if (tagged.length > 1) marks.innerTags = tagged.slice(1);
      if (deriveCue) marks.cue = true;
      result.push({ text: item.insert, marks });
    } else if ("k" in item.insert) {
      result.push({ atom: "broll", id: String(item.insert.k), text: String(item.insert.label ?? "B-roll:"), marks });
    } else if ("w" in item.insert) {
      const name = String(item.insert.w);
      result.push({ atom: "who", name, text: "@" + name, marks });
    } else throw new Error("Unsupported content atom");
  }
  return deriveCue ? settleCues(result) : result;
}

export function deltaToHtml(delta: readonly ProjectionDelta[], tags: unknown, comments: unknown, deriveCue = false): string {
  const registry = records(tags);
  return storedRunsToHtml(deltaToRuns(delta, registry, comments, deriveCue), id => {
    const tag = registry.find(entry => entry.id === id);
    return tag ? { cat: String(tag.cat), name: String(tag.name) } : defaultTagOf(id);
  });
}

export function insertHtml(text: Y.Text, html: string, tags: unknown, comments: unknown, scope: string): void {
  const delta = htmlToDelta(html, tags, comments);
  for (const item of delta) item.attributes = Object.fromEntries(Object.entries(item.attributes ?? {}).map(([key, value]) => [
    key.startsWith("t:") || key.startsWith("l:") ? `${key.slice(0, 2)}${scope}:${key.slice(2)}` : key, value
  ]));
  text.applyDelta([{ retain: text.length }, ...delta]);
}

export function readDelta(text: Y.Text): ProjectionDelta[] {
  const delta = text.toDelta() as { insert: unknown; attributes?: Record<string, unknown> }[];
  return delta.map((item): ProjectionDelta => ({
    insert: typeof item.insert === "string" ? item.insert : bag(item.insert), attributes: item.attributes ?? {}
  }));
}

import type * as Y from "yjs";
import { mapValue } from "../schema.ts";

export type ProjectionBag = Record<string, unknown>;

export function bag(value: unknown): ProjectionBag {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error("Expected a document record");
  return value as ProjectionBag;
}

export function records(value: unknown): ProjectionBag[] {
  return Array.isArray(value) ? value.map(bag) : [];
}

export function copy<T>(value: T): T {
  return structuredClone(value);
}

export function rank(index: number): string {
  return String(index).padStart(10, "0");
}

export function ordered(values: ProjectionBag, keys: unknown): ProjectionBag {
  const result: ProjectionBag = {};
  for (const key of [...(Array.isArray(keys) ? keys as string[] : []), ...Object.keys(values)]) {
    if (Object.hasOwn(values, key)) Object.defineProperty(result, key, { value: values[key], enumerable: true, configurable: true, writable: true });
  }
  return result;
}

export function writeRecord(target: Y.Map<unknown>, source: ProjectionBag, fields: readonly string[]): void {
  target.set("keys", Object.keys(source));
  const extra: ProjectionBag = {};
  for (const [key, value] of Object.entries(source)) {
    if (fields.includes(key)) target.set(key, copy(value));
    else Object.defineProperty(extra, key, { value: copy(value), enumerable: true, configurable: true, writable: true });
  }
  target.set("extra", JSON.stringify(extra));
}

export function readRecord(source: Y.Map<unknown>, fields: readonly string[]): ProjectionBag {
  const result = JSON.parse(String(source.get("extra") ?? "{}")) as ProjectionBag;
  for (const key of fields) if (source.has(key)) result[key] = copy(source.get(key));
  return ordered(result, source.get("keys"));
}

export function ranked(source: Y.Map<unknown>): [string, Y.Map<unknown>][] {
  return [...source.entries()].map(([id, value]): [string, Y.Map<unknown>] => [id, mapValue(value)])
    .sort(([a, left], [b, right]) => {
      const l = String(left.get("rank")), r = String(right.get("rank"));
      return l < r ? -1 : l > r ? 1 : a < b ? -1 : a > b ? 1 : 0;
    });
}

import * as Y from "yjs";
import type { CollabCaret, CollabCharacter, CollabMarks, CollabModel, CollabRow, IdentityBook } from "./model.ts";
import type { SchemaCandidate } from "./schema.ts";

export interface ReplicaCaretAnchor {
  position: Y.RelativePosition;
  selectionEnd?: Y.RelativePosition;
}

export type ReplicaCarets = ReadonlyMap<string, ReplicaCaretAnchor>;

interface ReadSpan {
  row: CollabRow;
  text: Y.Text;
  start: number;
  end: number;
}

function sharedMap(value: unknown): Y.Map<unknown> {
  if (!(value instanceof Y.Map)) throw new Error("Reader expected Y.Map");
  return value as Y.Map<unknown>;
}

function sharedText(value: unknown): Y.Text {
  if (!(value instanceof Y.Text)) throw new Error("Reader expected Y.Text");
  return value;
}

function boundary(value: unknown): string {
  if (typeof value !== "object" || value === null || !("b" in value) || typeof value.b !== "string") {
    throw new Error("Reader encountered an unsupported boundary");
  }
  return value.b;
}

function attributes(value: unknown): CollabMarks {
  if (value === undefined) return {};
  if (value === null || typeof value !== "object") throw new Error("Invalid attributes");
  const result: Record<string, string | boolean> = {};
  for (const [key, attribute] of Object.entries(value)) {
    if (typeof attribute !== "boolean" && typeof attribute !== "string") throw new Error(`Unsupported mark ${key}`);
    if (key === "cmt" && typeof attribute === "string") result[`c:${attribute}`] = true;
    else result[key] = attribute;
  }
  return result;
}

export function readReplica(doc: Y.Doc, candidate: SchemaCandidate, identities: IdentityBook, anchors: ReplicaCarets = new Map()): CollabModel {
  const spans: ReadSpan[] = [];
  const seen = new Set<string>();
  const beats = doc.getMap("beats");
  const scan = (text: Y.Text, head?: unknown): void => {
    let current: ReadSpan | undefined;
    let index = 0;
    const begin = (id: string, start: number): void => {
      if (current) current.end = index;
      if (seen.has(id)) return;
      seen.add(id);
      const record = sharedMap(beats.get(id));
      const lengthSeconds = record.get("lengthSeconds");
      const row: CollabRow = { id, characters: [] };
      if (typeof lengthSeconds === "number") row.lengthSeconds = lengthSeconds;
      current = { row, text, start, end: text.length };
      spans.push(current);
    };
    if (head !== undefined) begin(boundary(head), 0);
    for (const operation of text.toDelta()) {
      const insert: unknown = operation.insert;
      if (typeof insert === "string") {
        if (!current) throw new Error("Reader found text before a boundary");
        for (let offset = 0; offset < insert.length; offset++) {
          const id = Y.createRelativePositionFromTypeIndex(text, index + offset, 0).item;
          if (!id) throw new Error("Reader found a character without identity");
          const identity = { client: id.client, clock: id.clock };
          current.row.characters.push({ identity, notation: identities.notation(identity), value: insert.charAt(offset), marks: attributes(operation.attributes), beat: current.row.id });
        }
        index += insert.length;
      } else {
        begin(boundary(insert), index + 1);
        index++;
      }
    }
  };
  if (candidate === "A") {
    scan(doc.getText("flow"));
  } else {
    const segments = doc.getMap("segments");
    const ordered = new Set<string>();
    for (const id of doc.getArray<string>("order").toArray()) {
      if (ordered.has(id)) continue;
      ordered.add(id);
      const segment = sharedMap(segments.get(id));
      scan(sharedText(segment.get("text")), segment.get("head"));
    }
  }
  const model: CollabModel = { rows: [], carets: {}, recovery: [] };
  const destinations = new Map<string, { row: CollabRow; prefix: number }>();
  for (const span of spans) {
    const record = sharedMap(beats.get(span.row.id));
    const removals = sharedMap(record.get("removals"));
    if (removals.size > 0) {
      const removal = sharedMap(doc.getMap("removalRecords").get([...removals.keys()].sort()[0] ?? ""));
      const observed = removal.get("observed") as { client: number; clock: number; len: number }[];
      const edited = span.row.characters.filter(character => !observed.some(range => character.identity?.client === range.client && character.identity.clock >= range.clock && character.identity.clock < range.clock + range.len)).map(character => character.notation);
      model.recovery.push({ row: span.row, by: String(removal.get("by")), edited });
      continue;
    }
    const joins = sharedMap(record.get("joins"));
    const join = joins.get([...joins.keys()].sort()[0] ?? "") as { into: string; glue: string } | undefined;
    const target = join ? destinations.get(join.into) : undefined;
    if (join && !target) throw new Error("Probe requires an earlier live join target");
    if (target && join) {
      if (join.glue) {
        const glue: CollabCharacter = { identity: null, notation: "[glue]", value: join.glue, marks: {}, beat: target.row.id };
        target.row.characters.push(glue);
      }
      destinations.set(span.row.id, { row: target.row, prefix: target.row.characters.length });
      target.row.characters.push(...span.row.characters.map(character => ({ ...character, beat: target.row.id })));
    } else {
      model.rows.push(span.row);
      destinations.set(span.row.id, { row: span.row, prefix: 0 });
    }
  }
  const locateCaret = (position: Y.RelativePosition): CollabCaret => {
    const absolute = Y.createAbsolutePositionFromRelativePosition(position, doc, false);
    if (!absolute) throw new Error("Caret identity is unavailable");
    const span = spans.find(item => item.text === absolute.type && item.start <= absolute.index && absolute.index <= item.end);
    if (!span) throw new Error(`Caret is outside a beat at ${absolute.index}`);
    const destination = destinations.get(span.row.id);
    if (destination) return { beat: destination.row.id, offset: destination.prefix + absolute.index - span.start };
    const after = spans.slice(spans.indexOf(span) + 1).find(item => destinations.has(item.row.id));
    const fallback = after ? destinations.get(after.row.id) : [...destinations.values()].at(-1);
    if (!fallback) throw new Error("Caret recovery requires a surviving beat in this probe");
    return { beat: fallback.row.id, offset: after ? 0 : fallback.row.characters.length };
  };
  for (const [writer, anchor] of anchors) {
    const caret = locateCaret(anchor.position);
    model.carets[writer] = caret;
    if (anchor.selectionEnd) {
      const end = locateCaret(anchor.selectionEnd);
      caret.selection = { beat: end.beat, from: caret.offset, to: end.offset };
    }
  }
  return model;
}

import * as Y from "yjs";
import type { CollabIdentity, CollabMarks } from "./model.ts";
import type { IdentityBook } from "./model.ts";

export type SchemaCandidate = "A" | "B";

export interface SeedBeat {
  id: string;
  text: string;
  lengthSeconds?: number;
  kind?: "heading";
}

export interface LocatedCharacter {
  identity: CollabIdentity;
  value: string;
  beat: string;
  text: Y.Text;
  index: number;
}

export interface BeatLocation {
  text: Y.Text;
  start: number;
  end: number;
}

export interface UndoIdentityAnchor {
  notation: string;
  position: Y.RelativePosition;
}

export function mapValue(value: unknown): Y.Map<unknown> {
  if (!(value instanceof Y.Map)) throw new Error("Expected a shared map");
  return value as Y.Map<unknown>;
}

export function textValue(value: unknown): Y.Text {
  if (!(value instanceof Y.Text)) throw new Error("Expected shared text");
  return value;
}

export function identityAt(text: Y.Text, index: number): CollabIdentity {
  const identity = Y.createRelativePositionFromTypeIndex(text, index, 0).item;
  if (!identity) throw new Error(`No identity at ${index}`);
  return { client: identity.client, clock: identity.clock };
}

export function initializeSchemaRoots(doc: Y.Doc, candidate: SchemaCandidate): void {
  if (candidate === "A") doc.getText("flow");
  else {
    doc.getMap("segments");
    doc.getArray("order");
  }
  for (const name of ["beats", "visuals", "gallery", "comments", "replies", "people", "tags", "shots", "meta", "removalRecords", "retiredJoins", "statusEvents", "retiredStatus"]) doc.getMap(name);
}

export class SchemaReplica {
  readonly doc: Y.Doc;
  readonly localOrigin = {};
  readonly candidate: SchemaCandidate;
  readonly identities: IdentityBook;

  constructor(candidate: SchemaCandidate, client: number, identities: IdentityBook, initializeRoots = true) {
    this.doc = new Y.Doc();
    this.doc.clientID = client;
    this.candidate = candidate;
    this.identities = identities;
    if (initializeRoots) initializeSchemaRoots(this.doc, candidate);
  }

  private texts(): { text: Y.Text; head: string | null }[] {
    if (this.candidate === "A") return [{ text: this.doc.getText("flow"), head: null }];
    const segments = this.doc.getMap("segments");
    return [...new Set(this.doc.getArray<string>("order").toArray())].map(id => {
      const segment = mapValue(segments.get(id));
      const head = segment.get("head") as { b?: string; h?: string };
      return { text: textValue(segment.get("text")), head: head.b ?? head.h ?? null };
    });
  }

  characters(): LocatedCharacter[] {
    const result: LocatedCharacter[] = [];
    for (const { text, head } of this.texts()) {
      let beat = head;
      let index = 0;
      for (const delta of text.toDelta()) {
        const insert: unknown = delta.insert;
        if (typeof insert === "string") {
          for (let offset = 0; offset < insert.length; offset++) {
            if (!beat) throw new Error("Character outside a beat");
            result.push({ identity: identityAt(text, index + offset), value: insert.charAt(offset), beat, text, index: index + offset });
          }
          index += insert.length;
        } else {
          if (typeof insert !== "object" || insert === null) {
            throw new Error("Unsupported feasibility atom");
          }
          beat = "b" in insert ? String(insert.b) : "h" in insert ? String(insert.h) : null;
          index++;
        }
      }
    }
    return result;
  }

  locate(beatId: string): BeatLocation {
    for (const { text, head } of this.texts()) {
      let beat = head;
      let start = 0;
      let index = 0;
      for (const delta of text.toDelta()) {
        const insert: unknown = delta.insert;
        if (typeof insert === "string") {
          index += insert.length;
        } else {
          if (beat === beatId) return { text, start, end: index };
          if (typeof insert !== "object" || insert === null) {
            throw new Error("Unsupported feasibility atom");
          }
          beat = "b" in insert ? String(insert.b) : "h" in insert ? String(insert.h) : null;
          start = ++index;
        }
      }
      if (beat === beatId) return { text, start, end: index };
    }
    throw new Error(`Missing beat ${beatId}`);
  }

  private addBeat(id: string, lengthSeconds?: number): void {
    const beat = new Y.Map<unknown>();
    this.doc.getMap("beats").set(id, beat);
    beat.set("joins", new Y.Map<unknown>());
    beat.set("removals", new Y.Map<unknown>());
    if (lengthSeconds !== undefined) beat.set("lengthSeconds", lengthSeconds);
  }

  seed(beats: readonly SeedBeat[]): void {
    let serial = 1;
    this.doc.transact(() => {
      for (const beat of beats) {
        let text: Y.Text;
        if (this.candidate === "A") {
          text = this.doc.getText("flow");
          text.insertEmbed(text.length, beat.kind === "heading" ? { h: beat.id } : { b: beat.id }, {});
        } else {
          const segment = new Y.Map<unknown>();
          this.doc.getMap("segments").set(`seg-${beat.id}`, segment);
          text = new Y.Text();
          segment.set("text", text);
          segment.set("head", beat.kind === "heading" ? { h: beat.id } : { b: beat.id });
          this.doc.getArray<string>("order").push([`seg-${beat.id}`]);
        }
        const start = text.length;
        text.insert(start, beat.text, {});
        for (let offset = 0; offset < beat.text.length; offset++) {
          this.identities.bind(`s${serial++}`, identityAt(text, start + offset));
        }
      }
      for (const beat of beats) this.addBeat(beat.id, beat.lengthSeconds);
    }, "seed");
  }

  insert(beat: string, offset: number, value: string, names: readonly string[], marks: CollabMarks = {}): void {
    if (names.length !== value.length) throw new Error("One notation per UTF-16 character is required");
    this.doc.transact(() => {
      const { text, start, end } = this.locate(beat);
      if (offset < 0 || start + offset > end) throw new Error(`Offset outside ${beat}`);
      text.insert(start + offset, value, marks);
      names.forEach((name, index) => this.identities.bind(name, identityAt(text, start + offset + index)));
    }, this.localOrigin);
  }

  deleteIdentities(names: readonly string[]): void {
    const wanted = new Set(names.map(name => {
      const identity = this.identities.identity(name);
      return `${identity.client}:${identity.clock}`;
    }));
    const locations = this.characters().filter(character => wanted.has(`${character.identity.client}:${character.identity.clock}`));
    this.doc.transact(() => {
      for (const character of locations.reverse()) character.text.delete(character.index, 1);
    }, this.localOrigin);
  }

  format(beat: string, offset: number, length: number, marks: CollabMarks): void {
    this.doc.transact(() => {
      const { text, start } = this.locate(beat);
      text.format(start + offset, length, marks);
    }, this.localOrigin);
  }

  split(beat: string, offset: number, newBeat: string, name: string, by?: string): void {
    this.doc.transact(() => {
      const { text, start } = this.locate(beat);
      text.insertEmbed(start + offset, { b: newBeat }, {});
      this.identities.bind(name, identityAt(text, start + offset));
      this.addBeat(newBeat);
      if (by) mapValue(this.doc.getMap("beats").get(newBeat)).set("splitBy", by);
    }, this.localOrigin);
  }

  remove(beatId: string, removalId: string, by: string, observed?: readonly CollabIdentity[]): void {
    this.doc.transact(() => {
      const beat = mapValue(this.doc.getMap("beats").get(beatId));
      mapValue(beat.get("removals")).set(removalId, true);
      const record = new Y.Map<unknown>();
      this.doc.getMap("removalRecords").set(removalId, record);
      record.set("kind", "beat");
      record.set("by", by);
      record.set("at", 0);
      record.set("beat", beatId);
      record.set("observed", (observed ?? this.characters().filter(character => character.beat === beatId).map(character => character.identity)).map(identity => ({ ...identity, len: 1 })));
      record.set("atoms", []);
      record.set("components", []);
    }, this.localOrigin);
  }

  restore(beatId: string, removalId: string): void {
    this.doc.transact(() => {
      mapValue(mapValue(this.doc.getMap("beats").get(beatId)).get("removals")).delete(removalId);
    }, this.localOrigin);
  }

  join(from: string, into: string, id: string): void {
    this.doc.transact(() => {
      const left = this.locate(into);
      const right = this.locate(from);
      const glue = left.end > left.start && right.end > right.start ? " " : "";
      mapValue(mapValue(this.doc.getMap("beats").get(from)).get("joins")).set(id, { into, glue });
    }, this.localOrigin);
  }

  undoManager(): Y.UndoManager {
    const scopes: Y.AbstractType<unknown>[] = this.candidate === "A"
      ? [this.doc.getText("flow") as Y.AbstractType<unknown>]
      : [this.doc.getMap("segments") as Y.AbstractType<unknown>];
    scopes.push(this.doc.getMap("beats") as Y.AbstractType<unknown>);
    return new Y.UndoManager(scopes, { trackedOrigins: new Set([this.localOrigin]), captureTimeout: 1000 });
  }

  captureUndoIdentities(names: readonly string[]): UndoIdentityAnchor[] {
    return names.map(notation => {
      const identity = this.identities.identity(notation);
      const character = this.characters().find(item => item.identity.client === identity.client && item.identity.clock === identity.clock);
      if (!character) throw new Error(`Cannot capture absent identity ${notation}`);
      return { notation, position: Y.createRelativePositionFromTypeIndex(character.text, character.index, 0) };
    });
  }

  bindUndoRestores(anchors: readonly UndoIdentityAnchor[]): void {
    for (const anchor of anchors) {
      const position = Y.createAbsolutePositionFromRelativePosition(anchor.position, this.doc, true);
      if (!position || !(position.type instanceof Y.Text)) throw new Error(`Undo did not restore ${anchor.notation}`);
      const identity = identityAt(position.type, position.index);
      const original = this.identities.identity(anchor.notation);
      if (identity.client === original.client && identity.clock === original.clock) throw new Error(`Undo reused ${anchor.notation}`);
      this.identities.bind(`${anchor.notation}*`, identity);
    }
  }

  destroy(): void {
    this.doc.destroy();
  }
}

import * as Y from "yjs";
import type { CollabCharacter, CollabMarks, CollabModel, CollabRow, IdentityBook } from "./model.ts";
import type { ReplicaCarets } from "./reader.ts";
import type { SchemaCandidate } from "./schema.ts";
import { projectComments, projectStatus, projectStructuralMarks } from "./marks/projection.ts";

interface StructureSpan {
  row: CollabRow;
  text: Y.Text;
  start: number;
  end: number;
}

function record(value: unknown): Y.Map<unknown> {
  if (!(value instanceof Y.Map)) throw new Error("Structural reader expected a map");
  return value as Y.Map<unknown>;
}

function textRecord(value: unknown): Y.Text {
  if (!(value instanceof Y.Text)) throw new Error("Structural reader expected text");
  return value;
}

function marksOf(value: unknown): CollabMarks {
  if (value === undefined) return {};
  if (!value || typeof value !== "object") throw new Error("Invalid structural marks");
  const marks: Record<string, string | boolean> = {};
  for (const [key, mark] of Object.entries(value)) {
    if (typeof mark !== "string" && typeof mark !== "boolean") throw new Error(`Invalid mark ${key}`);
    marks[key] = mark;
  }
  return marks;
}

function readCharacters(text: Y.Text, start: number, value: string, marks: CollabMarks, beat: string, book: IdentityBook): CollabCharacter[] {
  return Array.from({ length: value.length }, (_, offset) => {
    const id = Y.createRelativePositionFromTypeIndex(text, start + offset, 0).item;
    if (!id) throw new Error("Missing structural character identity");
    const identity = { client: id.client, clock: id.clock };
    return { identity, notation: book.notation(identity), value: value.charAt(offset), marks, beat };
  });
}

export function readStructure(doc: Y.Doc, candidate: SchemaCandidate, book: IdentityBook, carets: ReplicaCarets = new Map()): CollabModel {
  const spans: StructureSpan[] = [];
  const seen = new Set<string>();
  const scan = (text: Y.Text, head?: unknown): void => {
    let current: StructureSpan | undefined;
    let index = 0;
    const begin = (value: unknown, start: number): void => {
      const boundary = value as { b?: string; h?: string };
      const id = boundary.b ?? boundary.h;
      if (!id) throw new Error("Unsupported structural atom");
      if (seen.has(id)) return;
      if (current) current.end = index;
      seen.add(id);
      current = { row: { id, characters: [], ...(boundary.h ? { kind: "heading" } : {}) }, text, start, end: text.length };
      spans.push(current);
    };
    if (head) begin(head, 0);
    for (const delta of text.toDelta()) {
      const insert: unknown = delta.insert;
      if (typeof insert === "string") {
        if (!current) throw new Error("Text outside structural boundary");
        current.row.characters.push(...readCharacters(text, index, insert, current.row.kind ? {} : marksOf(delta.attributes), current.row.id, book));
        index += insert.length;
      } else {
        begin(insert, index + 1);
        index++;
      }
    }
  };
  if (candidate === "A") scan(doc.getText("flow"));
  else {
    const ordered = new Set<string>();
    for (const id of doc.getArray<string>("order").toArray()) {
      if (ordered.has(id)) continue;
      ordered.add(id);
      const segment = record(doc.getMap("segments").get(id));
      scan(textRecord(segment.get("text")), segment.get("head"));
    }
  }
  const model: CollabModel = { rows: spans.map(span => span.row), carets: {}, recovery: [] };
  for (const row of model.rows) if (!row.kind) {
    const beat = record(doc.getMap("beats").get(row.id));
    if (typeof beat.get("status") === "string") row.status = String(beat.get("status"));
  }
  projectStatus(model, doc);
  model.rows = [];
  const destinations = new Map<string, { row: CollabRow; prefix: number }>();
  const activeRemovals: Y.Map<unknown>[] = [];
  for (const value of doc.getMap("beats").values()) {
    for (const id of record(record(value).get("removals")).keys()) {
      const removal = record(doc.getMap("removalRecords").get(id));
      if (removal.get("kind") !== "became-heading") activeRemovals.push(removal);
    }
  }
  const hasIdentity = (character: CollabCharacter, removal: Y.Map<unknown>): boolean => {
    return (removal.get("observed") as { client: number; clock: number; len: number }[]).some(range =>
      range.client === character.identity?.client && character.identity.clock >= range.clock && character.identity.clock < range.clock + range.len);
  };
  for (const span of spans) {
    const row = span.row;
    if (row.kind) {
      if (row.characters.length > 0) model.rows.push(row);
      destinations.set(row.id, { row, prefix: 0 });
      continue;
    }
    const beat = record(doc.getMap("beats").get(row.id));
    if (beat.get("paragraphStart") === true) row.paragraphStart = true;
    const removal = activeRemovals.find(item => item.get("beat") === row.id || row.characters.some(character => hasIdentity(character, item)));
    if (removal) {
      const splitBy = removal.get("beat") === row.id ? undefined : beat.get("splitBy");
      model.recovery.push({ row, by: String(removal.get("by")), edited: row.characters.filter(character => !hasIdentity(character, removal)).map(character => character.notation), ...(typeof splitBy === "string" ? { splitBy } : {}) });
      continue;
    }
    const joins = record(beat.get("joins"));
    const id = [...joins.keys()].filter(key => !doc.getMap("retiredJoins").has(key)).sort()[0];
    const join = id ? joins.get(id) as { into: string; glue: string } : undefined;
    const target = join ? destinations.get(join.into) : undefined;
    if (join && !target) throw new Error("Structural join target unavailable");
    if (join && target) {
      if (join.glue) target.row.characters.push({ identity: null, notation: "[glue]", value: join.glue, marks: {}, beat: target.row.id });
      destinations.set(row.id, { row: target.row, prefix: target.row.characters.length });
      target.row.characters.push(...row.characters.map(character => ({ ...character, beat: target.row.id })));
      const ranks = ["todo", "ready", "shot"];
      if (row.status && ranks.indexOf(row.status) > ranks.indexOf(target.row.status ?? "todo")) target.row.status = row.status;
    } else {
      model.rows.push(row);
      destinations.set(row.id, { row, prefix: 0 });
    }
  }
  for (const [componentId, value] of doc.getMap("visuals")) {
    const component = record(value);
    const origin = String(component.get("beat"));
    const target = destinations.get(origin)?.row ?? model.recovery.find(item => item.row.id === origin)?.row;
    if (!target) continue;
    const text = textRecord(component.get("text"));
    const visual: CollabRow = { id: componentId, characters: [] };
    let index = 0;
    for (const delta of text.toDelta()) {
      const insert: unknown = delta.insert;
      if (typeof insert !== "string") throw new Error("Unsupported visual atom");
      visual.characters.push(...readCharacters(text, index, insert, marksOf(delta.attributes), componentId, book));
      index += insert.length;
    }
    (target.visuals ??= []).push(visual);
    target.visualText = target.visuals.filter(item => item.characters.length > 0).map(item => item.characters.map(character => character.value).join("")).join("<br>");
  }
  const gallery = [...doc.getMap("gallery").values()] as { id: string; beat: string; rank: string; ref: string; name: string; annotation: string; links: { href: string; poster?: string }[] }[];
  for (const item of gallery.sort((a, b) => (spans.findIndex(span => span.row.id === a.beat) - spans.findIndex(span => span.row.id === b.beat)) || a.rank.localeCompare(b.rank) || a.id.localeCompare(b.id))) {
    const target = destinations.get(item.beat)?.row ?? model.recovery.find(entry => entry.row.id === item.beat)?.row;
    if (!target) continue;
    const items = (target.gallery ??= []) as { ref: string; name: string; annotation: string; links: { href: string; poster?: string }[] }[];
    const existing = items.find(entry => entry.ref === item.ref);
    if (!existing) items.push({ ref: item.ref, name: item.name, annotation: item.annotation, links: structuredClone(item.links) });
    else {
      existing.name ||= item.name;
      existing.annotation ||= item.annotation;
      for (const link of item.links) {
        const old = existing.links.find(entry => entry.href === link.href);
        if (!old) existing.links.push({ ...link });
        else if (!old.poster && link.poster) old.poster = link.poster;
      }
    }
  }
  if (gallery.length) model.records = { gallery: Object.fromEntries([...doc.getMap("gallery")].sort(([a], [b]) => a.localeCompare(b))) };
  const locate = (position: Y.RelativePosition): { beat: string; offset: number } => {
    const absolute = Y.createAbsolutePositionFromRelativePosition(position, doc, false);
    if (!absolute) throw new Error("Structural caret missing");
    const span = spans.find(item => item.text === absolute.type && item.start <= absolute.index && absolute.index <= item.end);
    if (!span) {
      for (const [id, component] of doc.getMap("visuals")) {
        const value = record(component);
        if (value.get("text") === absolute.type) {
          const target = destinations.get(String(value.get("beat")));
          if (!target) throw new Error("Visual caret in recovery");
          const prefix = target.row.visuals?.slice(0, target.row.visuals.findIndex(visual => visual.id === id)).reduce((sum, visual) => sum + visual.characters.length + 1, 0) ?? 0;
          return { beat: `${target.row.id}:visual`, offset: prefix + absolute.index };
        }
      }
      throw new Error(`Caret outside structural span at ${absolute.index}`);
    }
    const destination = destinations.get(span.row.id);
    if (destination) return { beat: destination.row.id, offset: destination.prefix + absolute.index - span.start };
    const after = spans.slice(spans.indexOf(span) + 1).find(item => !item.row.kind && destinations.has(item.row.id));
    const fallback = after ? destinations.get(after.row.id) : [...destinations.values()].filter(item => !item.row.kind).at(-1);
    if (!fallback) throw new Error("No surviving caret destination");
    return { beat: fallback.row.id, offset: after ? 0 : fallback.row.characters.length };
  };
  for (const [writer, caret] of carets) {
    const start = locate(caret.position);
    model.carets[writer] = start;
    if (caret.selectionEnd) {
      const end = locate(caret.selectionEnd);
      model.carets[writer] = { ...start, selection: { beat: end.beat, from: start.offset, to: end.offset } };
    }
  }
  projectStructuralMarks(model, doc);
  projectComments(model, doc);
  return model;
}

import * as Y from "yjs";
import { identityAt, mapValue, textValue } from "./schema.ts";
import type { SchemaReplica } from "./schema.ts";

export function structureManager(replica: SchemaReplica): Y.UndoManager {
  return new Y.UndoManager([
    replica.doc.getText("flow"), replica.doc.getMap("segments"), replica.doc.getArray("order"),
    replica.doc.getMap("beats"), replica.doc.getMap("comments"), replica.doc.getMap("replies"), replica.doc.getMap("statusEvents")
  ] as Y.AbstractType<unknown>[], { trackedOrigins: new Set([replica.localOrigin]), captureTimeout: 1000 });
}

export function undoOne(manager: Y.UndoManager): void {
  const earlier = manager.undoStack.splice(0, Math.max(0, manager.undoStack.length - 1));
  try {
    manager.undo();
  } finally {
    manager.undoStack.unshift(...earlier);
  }
}

export function undoJoin(replica: SchemaReplica, manager: Y.UndoManager, from: string, into: string): void {
  const joins = mapValue(mapValue(replica.doc.getMap("beats").get(from)).get("joins"));
  replica.doc.transact(() => {
    for (const [id, value] of joins) {
      if ((value as { into: string }).into === into) replica.doc.getMap("retiredJoins").set(id, true);
    }
  }, "semantic-undo");
  manager.undoStack.pop();
}

export function clearGlue(replica: SchemaReplica, from: string): void {
  replica.doc.transact(() => {
    const joins = mapValue(mapValue(replica.doc.getMap("beats").get(from)).get("joins"));
    for (const [id, value] of joins) joins.set(id, { ...(value as object), glue: "" });
  }, replica.localOrigin);
}

function replaceBoundary(replica: SchemaReplica, id: string, head: { b: string } | { h: string }): void {
  const { text, start } = replica.locate(id);
  if (start === 0 && replica.candidate === "B") {
    for (const value of replica.doc.getMap("segments").values()) {
      const segment = mapValue(value);
      if (textValue(segment.get("text")) === text) segment.set("head", head);
    }
  } else {
    text.delete(start - 1, 1);
    text.insertEmbed(start - 1, head, {});
  }
}

function addRecord(replica: SchemaReplica, id: string): void {
  const record = new Y.Map<unknown>();
  replica.doc.getMap("beats").set(id, record);
  record.set("joins", new Y.Map());
  record.set("removals", new Y.Map());
}

export function removeHeading(replica: SchemaReplica, heading: string, newBeat: string, next: string): void {
  replica.doc.transact(() => {
    replaceBoundary(replica, heading, { b: newBeat });
    addRecord(replica, newBeat);
    mapValue(replica.doc.getMap("beats").get(next)).set("paragraphStart", true);
  }, replica.localOrigin);
}

export function createHeading(replica: SchemaReplica, beat: string, heading: string, nameLength: number, follows: boolean, names: readonly string[]): void {
  replica.doc.transact(() => {
    const location = replica.locate(beat);
    location.text.delete(location.start, 2);
    if (follows) location.text.delete(location.start + nameLength, 1);
    replaceBoundary(replica, beat, { h: heading });
    addRecord(replica, heading);
    const converted = replica.locate(heading);
    if (converted.start > 0) replica.identities.bind(names[0] ?? "heading", identityAt(converted.text, converted.start - 1));
    if (follows) {
      converted.text.insertEmbed(converted.start + nameLength, { b: beat }, {});
      replica.identities.bind(names[1] ?? "boundary", identityAt(converted.text, converted.start + nameLength));
    } else {
      mapValue(mapValue(replica.doc.getMap("beats").get(beat)).get("removals")).set(`became-${heading}`, true);
      const removal = new Y.Map<unknown>();
      replica.doc.getMap("removalRecords").set(`became-${heading}`, removal);
      removal.set("kind", "became-heading");
    }
  }, replica.localOrigin);
}

export function moveBeat(replica: SchemaReplica, beat: string, before: string | null): boolean {
  if (replica.candidate === "A") return false;
  const order = replica.doc.getArray<string>("order");
  const segmentId = `seg-${beat}`;
  const segment = mapValue(replica.doc.getMap("segments").get(segmentId));
  const text = textValue(segment.get("text"));
  if (text.toDelta().some((delta: { insert: unknown }) => typeof delta.insert !== "string")) return false;
  replica.doc.transact(() => {
    for (let index = order.length - 1; index >= 0; index--) if (order.get(index) === segmentId) order.delete(index, 1);
    const index = before === null ? order.length : order.toArray().indexOf(`seg-${before}`);
    if (index < 0) throw new Error("Missing move destination");
    order.insert(index, [segmentId]);
  }, replica.localOrigin);
  return true;
}

export function cutPaste(): boolean {
  return false;
}

export function seedJoinMetadata(replica: SchemaReplica): void {
  replica.doc.transact(() => {
    mapValue(replica.doc.getMap("beats").get("R1")).set("status", "todo");
    mapValue(replica.doc.getMap("beats").get("R2")).set("status", "ready");
    for (const [id, beat, value, notation] of [["V1", "R1", "v", "v1"], ["V2", "R2", "w", "w1"]]) {
      if (!id || !beat || !value || !notation) throw new Error("Incomplete visual seed");
      const component = new Y.Map<unknown>();
      replica.doc.getMap("visuals").set(id, component);
      component.set("beat", beat);
      component.set("rank", "0");
      const text = new Y.Text();
      component.set("text", text);
      text.insert(0, value, {});
      replica.identities.bind(notation, identityAt(text, 0));
    }
    const items = [
      { id: "gP1", beat: "R1", rank: "0", ref: "P", name: "", annotation: "", links: [{ href: "https://v/1" }] },
      { id: "gP2", beat: "R2", rank: "0", ref: "P", name: "wide", annotation: "", links: [{ href: "https://v/1", poster: "poster" }, { href: "https://v/2" }] },
      { id: "gQ", beat: "R2", rank: "1", ref: "Q", name: "", annotation: "", links: [] }
    ];
    for (const item of items) replica.doc.getMap("gallery").set(item.id, item);
  }, "fixture");
}

export function visualInsert(replica: SchemaReplica, component: string, offset: number, value: string, notation: string): Y.RelativePosition {
  const text = textValue(mapValue(replica.doc.getMap("visuals").get(component)).get("text"));
  replica.doc.transact(() => {
    text.insert(offset, value, {});
    replica.identities.bind(notation, identityAt(text, offset));
  }, replica.localOrigin);
  return Y.createRelativePositionFromTypeIndex(text, offset + value.length, -1);
}
